/// <reference types="vitest/config" />
import { defineConfig } from 'vite'
import { readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
export default defineConfig({
  base: './',
  plugins: [{
    name: 'alta-export-inventory',
    enforce: 'post',
    generateBundle(_options, bundle) {
      const paths = ['index.html', 'package.json', 'package-lock.json', 'vite.config.ts', 'tsconfig.json', 'README.md', 'GAME_DESIGN_DOCUMENT.md',
        ...readdirSync('design/ATLA').filter(name => /\.(js|css|html|json)$/.test(name)).map(name => `design/ATLA/${name}`)]
      const sources = Object.fromEntries(paths.map(path => [path, readFileSync(resolve(path), 'utf8')]))
      const draco = ['draco_decoder.js', 'draco_decoder.wasm', 'draco_wasm_wrapper.js'].map(name => `alta-draco/${name}`)
      this.emitFile({ type: 'asset', fileName: 'alta-export.json', source: JSON.stringify({ sources, files: [...Object.keys(bundle), ...draco] }) })
    },
  }],
  resolve: {
    tsconfigPaths: true,
  },
  server: {
    host: '127.0.0.1',
    strictPort: true,
  },
  preview: {
    host: '127.0.0.1',
    strictPort: true,
  },
  test: {
    environment: 'jsdom',
    setupFiles: ['./tests/setup.ts'],
  },
})

