// Optional: if you ever deploy a Cloudflare Worker proxy, paste its URL here
const WORKER_PROXY_URL = "";

const SYSTEM_PROMPT = `You are ALTA, a sharp, helpful AI study tutor inside a 3D study room.
Explain concepts clearly step-by-step in plain language (or Tamil/Tanglish if asked) and keep answers concise and practical.`;

export async function askStudyAI({ history = [], studyContext = "", signal, rawSystemPrompt = "" }) {
  const systemContent = rawSystemPrompt
    ? rawSystemPrompt
    : studyContext
      ? `${SYSTEM_PROMPT}\n\nStudent's Active Study Material / Notes:\n${studyContext.slice(0, 5000)}`
      : SYSTEM_PROMPT;

  const messages = [
    { role: "system", content: systemContent },
    ...history
      .filter((m) => (m.role === "user" || m.role === "assistant") && m.content?.trim())
      .slice(-10)
      .map((m) => ({ role: m.role, content: m.content })),
  ];

  // 1. Optional Worker Proxy
  if (WORKER_PROXY_URL) {
    try {
      const res = await fetch(WORKER_PROXY_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ messages }),
        signal,
      });
      if (res.ok) {
        const data = await res.json();
        const reply = data?.reply || data?.choices?.[0]?.message?.content?.trim();
        if (reply) return { reply, provider: "ALTA Cloud AI" };
      }
    } catch (err) {
      if (err?.name === "AbortError") throw err;
    }
  }

  // 2. Live Zero-Key AI (Pollinations OpenAI-compatible endpoint)
  try {
    const res = await fetch("https://text.pollinations.ai/openai", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ model: "openai", messages }),
      signal,
    });
    if (res.ok) {
      const data = await res.json();
      const reply = data?.choices?.[0]?.message?.content?.trim();
      if (reply) return { reply, provider: "ALTA Live AI" };
    }
  } catch (err) {
    if (err?.name === "AbortError") throw err;
  }

  // 3. Secondary Live Zero-Key Fallback (Pollinations raw text endpoint)
  try {
    const res = await fetch("https://text.pollinations.ai/", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ model: "openai", messages }),
      signal,
    });
    if (res.ok) {
      const text = (await res.text()).trim();
      if (text) return { reply: text, provider: "ALTA Live AI" };
    }
  } catch (err) {
    if (err?.name === "AbortError") throw err;
  }

  // 4. Final fallback: Puter.js
  if (window.puter?.ai?.chat) {
    const res = await window.puter.ai.chat(messages, false, { model: "gpt-5.4-nano" });
    const reply = typeof res === "string" ? res : res?.message?.content || String(res || "");
    if (reply.trim()) return { reply: reply.trim(), provider: "ALTA AI" };
  }

  throw new Error("Could not reach AI right now. Check your internet and try again.");
}

