import calmMusicUrl from "./sounds/calm music.mp3?url";
import doorSoundUrl from "./sounds/door open.mp3?url";
import catSoundUrl from "./sounds/cat sound.mp3?url";
import buttonSoundUrl from "./sounds/button press all.mp3?url";
import mouseSoundUrl from "./sounds/mouse click.mp3?url";
import keySoundUrl from "./sounds/single key keyboard.mp3?url";

const roomAssets = import.meta.glob("./assets/*.glb", { eager: true, query: "?url&no-inline", import: "default" });
const roomSounds = {
  "calm music.mp3": calmMusicUrl, "door open.mp3": doorSoundUrl, "cat sound.mp3": catSoundUrl,
  "button press all.mp3": buttonSoundUrl, "mouse click.mp3": mouseSoundUrl, "single key keyboard.mp3": keySoundUrl,
};
const STORAGE_PREFIX = "jabali:alta-study-room";
const calmMusic = new Audio(calmMusicUrl);
calmMusic.loop = true;
const soundEffects = Object.fromEntries(Object.entries({
  door: doorSoundUrl, cat: catSoundUrl, button: buttonSoundUrl,
  mouse: mouseSoundUrl, key: keySoundUrl,
}).map(([name, url]) => {
  const audio = new Audio(url);
  audio.volume = name === "key" ? 0.12 : 0.25;
  return [name, audio];
}));

function playSound(name) {
  const audio = soundEffects[name];
  audio.currentTime = 0;
  audio.play().catch(() => {});
}

function showToast(message) {
  const toast = document.getElementById("propToast");
  toast.textContent = message;
  toast.hidden = false;
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => { toast.hidden = true; }, 2800);
}

function toggleMasterMute() {
  state.masterMuted = !state.masterMuted;
  calmMusic.muted = state.masterMuted;
  Object.values(soundEffects).forEach(audio => { audio.muted = state.masterMuted; });
  if (state.masterMuted) state.catCompanion?.muteAmbient();
  renderIfOpen("audio");
  showToast(state.masterMuted ? "Room audio muted" : "Room audio unmuted");
}

function updateSfxVolume() {
  for (const [name, audio] of Object.entries(soundEffects)) {
    audio.volume = (name === "key" ? 0.12 : name === "cat" ? 0.26 : 0.25) * state.sfxVolume;
  }
}

function playBook() {
  const entry = state.animatedAssets.get("book");
  if (!entry?.animations.length || state.editorOpen) return;
  state.bookMixer ??= new THREE.AnimationMixer(entry.root);
  const action = state.bookMixer.clipAction(entry.animations[0]);
  action.reset().setLoop(THREE.LoopOnce, 1);
  action.clampWhenFinished = true;
  action.fadeIn(0.15).play();
}

function pulseProp(name, rustle = false) {
  if (state.propPulse) finishPropPulse();
  const root = state.assetObjects.get(name);
  if (!root) return;
  const position = getAssetWorldPosition(name);
  const light = new THREE.PointLight(rustle ? 0x8dddb0 : 0x8a7dff, 2, 1.2);
  light.position.copy(position);
  state.scene.add(light);
  state.propPulse = { root, light, start: performance.now(), baseX: root.position.x, rustle };
}

function finishPropPulse() {
  const pulse = state.propPulse;
  if (!pulse) return;
  pulse.root.position.x = pulse.baseX;
  state.scene.remove(pulse.light);
  pulse.light.dispose();
  state.propPulse = null;
}

function updatePropPulse() {
  const pulse = state.propPulse;
  if (!pulse) return;
  const t = (performance.now() - pulse.start) / 850;
  if (t >= 1) return finishPropPulse();
  pulse.light.intensity = Math.sin(Math.PI * t) * 3;
  if (pulse.rustle) pulse.root.position.x = pulse.baseX + Math.sin(t * Math.PI * 6) * (1 - t) * 1.2;
}

function toggleMonitorPower() {
  clearHoverState();
  state.monitorOn = !state.monitorOn;
  for (const name of ["left_monitor_screen", "right_monitor_screen"]) {
    const screen = monitorScreens[name];
    state.assetObjects.get(name)?.traverse(mesh => {
      if (!mesh.isMesh || !mesh.material) return;
      const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
      for (const material of mats) {
        if (state.monitorOn && screen) {
          material.color?.set(0xffffff);
          material.emissive?.set(0xffffff);
          material.map = screen.texture;
          material.emissiveMap = screen.texture;
          if ("emissiveIntensity" in material) material.emissiveIntensity = 0.75;
        } else {
          material.color?.set(0x05070b);
          material.emissive?.set(0x000000);
          material.map = null;
          material.emissiveMap = null;
          if ("emissiveIntensity" in material) material.emissiveIntensity = 0;
        }
        material.needsUpdate = true;
      }
    });
  }
  if (state.monitorOn) updateMonitorScreens();
  showToast(`Monitor power ${state.monitorOn ? "on" : "off"}`);
}

function toggleMicrophone() {
  if (state.micRequested) {
    state.micRequested = false;
    state.recognition?.stop();
    return;
  }
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SpeechRecognition) { showToast("Voice input is not supported by this browser"); return; }
  const recognition = new SpeechRecognition();
  state.recognition = recognition;
  recognition.continuous = true;
  recognition.interimResults = false;
  recognition.onstart = () => { document.getElementById("listeningBadge").hidden = false; };
  recognition.onresult = event => {
    const text = Array.from(event.results).slice(event.resultIndex).filter(result => result.isFinal).map(result => result[0].transcript).join(" ");
    if (!text) return;
    state.appData.tutor.draft = [state.appData.tutor.draft, text].filter(Boolean).join(" ");
    const field = dom.panelContent.querySelector("#tutorInput");
    if (field) field.value = state.appData.tutor.draft;
  };
  recognition.onerror = event => { showToast(`Voice input unavailable: ${event.error}`); };
  recognition.onend = () => {
    state.micRequested = false;
    document.getElementById("listeningBadge").hidden = true;
  };
  try { state.micRequested = true; recognition.start(); }
  catch { state.micRequested = false; showToast("Could not start voice input"); }
}

