function syncMonitorVideoFrame() {
  const frame = document.getElementById("monitorVideoFrame");
  const src = convertToEmbedUrl(state.appData.pomodoro.embedUrl);
  if (frame.dataset.src !== src) {
    frame.dataset.src = src;
    frame.src = src || "about:blank";
  }
}

function updateMonitorVideoOverlay() {
  const src = convertToEmbedUrl(state.appData.pomodoro.embedUrl);
  const obj = state.assetObjects.get("left_monitor_screen");
  if (!src || !obj || !state.entered || state.entering || state.editorOpen || !state.monitorOn || state.currentPanel) {
    monitorVideoOverlay.style.display = "none";
    return;
  }

  const box = new THREE.Box3().setFromObject(obj);
  const corners = [
    new THREE.Vector3(box.min.x, box.min.y, box.min.z),
    new THREE.Vector3(box.min.x, box.min.y, box.max.z),
    new THREE.Vector3(box.min.x, box.max.y, box.min.z),
    new THREE.Vector3(box.min.x, box.max.y, box.max.z),
    new THREE.Vector3(box.max.x, box.min.y, box.min.z),
    new THREE.Vector3(box.max.x, box.min.y, box.max.z),
    new THREE.Vector3(box.max.x, box.max.y, box.min.z),
    new THREE.Vector3(box.max.x, box.max.y, box.max.z),
  ];

  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  let visible = false;
  const w = window.innerWidth;
  const h = window.innerHeight;

  for (const c of corners) {
    c.project(state.camera);
    if (c.z < 1) visible = true;
    const x = (c.x * 0.5 + 0.5) * w;
    const y = (-c.y * 0.5 + 0.5) * h;
    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }

  const width = maxX - minX;
  const height = maxY - minY;
  if (!visible || width < 60 || height < 40 || maxX < 0 || minX > w || maxY < 0 || minY > h) {
    monitorVideoOverlay.style.display = "none";
    return;
  }

  monitorVideoOverlay.style.display = "block";
  monitorVideoOverlay.style.left = `${minX}px`;
  monitorVideoOverlay.style.top = `${minY}px`;
  monitorVideoOverlay.style.width = `${width}px`;
  monitorVideoOverlay.style.height = `${height}px`;
}

dom.guideButton.addEventListener("click", () => toggleGuide(true));
