init().catch((error) => {
  console.error("[ALTA] Study room startup failed", error);
  dom.loadingStatus.textContent = "The room couldn’t load. Reload the page and check that WebGL is available.";
});

async function init() {
  initThree();
  const deployedConfig = loadSceneConfig(`${import.meta.env.BASE_URL}scene-config.json`);
  state.sceneConfig = mergeSceneConfig(await deployedConfig, storage.load("scene-config", null));
  initLightingPopover();
  applySceneLighting();
  bindGlobalEvents();
  updateHud();
  renderWelcome();
  await loadRoom();
  syncMonitorVideoFrame();
  state.catCompanion = createCatCompanion({
    entry: state.animatedAssets.get("cat"), assets: state.assetObjects, camera: state.camera,
    sound: soundEffects.cat, sfxVolume: () => state.sfxVolume,
    ambientEnabled: () => state.entered && !state.masterMuted && !document.hidden,
  });
  const updateEditor = attachDevEditor({
    camera: state.camera, controls: state.controls, clips: state.animatedAssets,
    config: state.sceneConfig, applyLighting: applySceneLighting, readLighting: readSceneLighting,
    save: () => {
      try { storage.save("scene-config", state.sceneConfig); return true; }
      catch { return false; }
    },
    jump: (view, immediate) => jumpCamera(view, immediate, true), models: roomAssets, sounds: roomSounds,
    onAnimationTest: model => {
      state.catCompanion?.pauseForTester(model);
      if (model === "door") state.doorMixer?.stopAllAction();
      if (model === "book") state.bookMixer?.stopAllAction();
    },
    onOpenChange: open => {
      state.editorOpen = open;
      state.cameraTween = null;
      if (open) state.entering = false;
      clearHoverState();
      if (!open) resetDoorClosed();
      if (!open && !state.entered && !state.entering) {
        closePanel();
        jumpCamera("door", true, true);
      }
      updateEntryControls();
    },
  });
  startLoop(updateEditor);
  startTickers();
}

function initThree() {
  state.scene = new THREE.Scene();
  state.scene.background = new THREE.Color(0x0b0e1a);

  state.camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.05, 500);
  state.camera.position.set(0, 2, 4);

  state.renderer = new THREE.WebGLRenderer({
    canvas: dom.canvas, antialias: true, alpha: true,
    powerPreference: "high-performance", preserveDrawingBuffer: true,
  });
  state.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  state.renderer.setSize(window.innerWidth, window.innerHeight);
  state.renderer.outputColorSpace = THREE.SRGBColorSpace;
  state.renderer.toneMapping = THREE.ACESFilmicToneMapping;
  state.renderer.toneMappingExposure = 1.35;

  const pmrem = new THREE.PMREMGenerator(state.renderer);
  state.scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
  pmrem.dispose();

  state.controls = new OrbitControls(state.camera, dom.canvas);
  state.controls.enableDamping = true;
  state.controls.enablePan = true;
  state.controls.dampingFactor = 0.06;
  state.controls.minDistance = 0.4;
  state.controls.maxDistance = 12;
  state.controls.target.set(0, 1.5, 0);
  state.controls.addEventListener("start", () => { state.cameraTween = null; });

  const ambient = new THREE.AmbientLight(0xffe6cc, 1.4);
  const hemi = new THREE.HemisphereLight(0xfff0dd, 0x262c4d, 1.1);
  const key = new THREE.DirectionalLight(0xffe4c4, 2.0);
  key.position.set(4, 7, 4);
  const ceiling = new THREE.PointLight(0xffdfb8, 18, 25, 1.5);
  ceiling.position.set(0, 3.8, 0);
  state.ambient = ambient;
  state.hemi = hemi;
  state.keyLight = key;
  state.ceiling = ceiling;

  state.scene.add(ambient, hemi, key, ceiling, state.roomRoot);
}

function readSceneLighting() {
  return { toneMappingExposure: state.renderer.toneMappingExposure, ambientIntensity: state.ambient.intensity, ceilingIntensity: state.ceiling.intensity };
}

function applySceneLighting(changed) {
  const settings = state.lightingSettings;
  const theme = LIGHTING_THEMES[settings.themeId] || LIGHTING_THEMES.cozy;
  if (!changed) {
    state.scene.background.set(theme.bgColor);
    state.ambient.color.set(theme.ambientColor);
    state.hemi?.color.set(theme.hemiSkyColor);
    state.hemi?.groundColor.set(theme.hemiGroundColor);
    if (state.hemi) state.hemi.intensity = theme.hemiIntensity;
    state.keyLight?.color.set(theme.keyColor);
    if (state.keyLight) state.keyLight.intensity = theme.keyIntensity;
    state.ceiling.color.set(settings.ceilingColor);
  }
  const { toneMappingExposure, ambientIntensity, ceilingIntensity } = state.sceneConfig.lighting;
  state.ambient.intensity = ambientIntensity;
  state.ceiling.intensity = settings.ceilingEnabled ? ceilingIntensity : 0;
  if (changed && changed !== "toneMappingExposure") return;
  state.renderer.toneMappingExposure = toneMappingExposure;
  updateLightingUi();
}

function bindGlobalEvents() {
  window.addEventListener("resize", onResize);
  dom.closeLightingPopover.addEventListener("click", () => toggleLightingPopover(false));
  calmMusic.volume = state.musicVolume;
  updateSfxVolume();

  document.addEventListener("click", (event) => {
    const button = event.target.closest("button");
    if (button && button.dataset.action !== "cat-pet") playSound("button");
  });
  window.addEventListener("keydown", (event) => {
    if (event.repeat || event.ctrlKey || event.metaKey || event.altKey) return;
    const target = event.target;
    const typingInField = target instanceof HTMLElement && (target.isContentEditable || target.matches("textarea, input[type='text'], input[type='search'], input[type='url']"));
    const focusedOnKeyboard = state.hoveredAsset === "keyboard" || state.focus === "desk";
    if ((typingInField || (focusedOnKeyboard && state.entered && !state.editorOpen)) && (event.key.length === 1 || event.key === "Backspace" || event.key === "Enter" || event.key === "Space")) {
      playSound("key");
      pulseKeyboardVisual(event.key);
    }
  });

  dom.canvas.addEventListener("pointermove", onPointerMove);
  dom.canvas.addEventListener("pointerleave", clearHoverState);
  dom.canvas.addEventListener("pointerdown", (event) => {
    state.activePointers.add(event.pointerId);
    state.dragStart = state.activePointers.size === 1 && event.button === 0
      ? { x: event.clientX, y: event.clientY, moved: false } : null;
  });
  window.addEventListener("pointerup", event => state.activePointers.delete(event.pointerId));
  window.addEventListener("pointercancel", event => {
    state.activePointers.delete(event.pointerId);
    state.dragStart = null;
  });
  dom.canvas.addEventListener("click", onSceneClick);
  dom.backToRoom.addEventListener("click", backToRoom);
  window.addEventListener("keydown", event => {
    if (event.key !== "Escape" || state.editorOpen) return;
    if (!dom.lightingPopover.classList.contains("hidden")) { event.preventDefault(); toggleLightingPopover(false); return; }
    if (state.currentPanel) { closePanel(); return; }
    if (dom.backToRoom.hidden) return;
    event.preventDefault();
    backToRoom();
  });

  dom.closePanel.addEventListener("click", closePanel);
  dom.panelBackdrop.addEventListener("click", closePanel);
  dom.panelContent.addEventListener("click", handlePanelClick);
  dom.panelContent.addEventListener("input", handlePanelInput);
  dom.panelContent.addEventListener("change", handlePanelChange);
}

async function loadRoom() {
  const total = manifest.length;
  let processed = 0;
  updateProgress(0, total);

  const dracoLoader = new DRACOLoader();
  dracoLoader.setDecoderPath(`${import.meta.env.BASE_URL}alta-draco/`);
  const loader = new GLTFLoader();
  loader.setDRACOLoader(dracoLoader);

  await loadWithConcurrency(manifest, 3, async (fileName) => {
    const assetName = fileName.replace(/\.glb$/i, "");
    try {
      const assetUrl = roomAssets[`./assets/${fileName}`];
      if (!assetUrl) throw new Error(`Missing model: ${fileName}`);
      const gltf = await loadGLB(loader, assetUrl);
      const root = gltf.scene || gltf.scenes?.[0];
      if (!root) throw new Error(`No scene found in ${fileName}`);

      root.userData.assetName = assetName;
      state.assetObjects.set(assetName, root);
      const animations = filterRoomClips(assetName, gltf.animations || []);
      if (animations.length) state.animatedAssets.set(assetName, { root, animations });
      if (isPoster(assetName, root)) state.posters.add(assetName);

      root.traverse((child) => {
        if (!child.isMesh) return;
        const groupName = isKeyboardAsset(assetName) ? "keyboard" : isMouseAsset(assetName) ? "mouse" : assetName;
        child.userData.assetName = groupName;
        child.castShadow = false;
        child.receiveShadow = true;

        const materials = Array.isArray(child.material) ? child.material : [child.material];
        materials.filter(Boolean).forEach((material) => {
          if ("envMapIntensity" in material) material.envMapIntensity = 0.9;
          if ("roughness" in material) material.roughness = Math.min(material.roughness, 1);
        });

        if (INTERACTIVE_ASSETS[groupName] || groupName === "keyboard" || groupName === "mouse" || state.posters.has(assetName)) {
          state.interactiveMeshes.push(child);
        }
      });

      state.roomRoot.add(root);
    } catch (error) {
      console.error(`Failed to load ${fileName}`, error);
    } finally {
      processed += 1;
      updateProgress(processed, total);
    }
  });

  dracoLoader.dispose();
  if (!state.assetObjects.size) throw new Error("No room models loaded");
  finalizeRoomSetup();
}

async function loadGLB(loader, url) {
  const maxRetries = 3;
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      const response = await fetch(url);
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const buffer = await response.arrayBuffer();
      return await new Promise((resolve, reject) => {
        loader.parse(buffer, url.replace(/^.*\//, ""), resolve, reject);
      });
    } catch (error) {
      if (attempt === maxRetries) throw error;
      await new Promise((r) => setTimeout(r, 300 * attempt));
    }
  }
}

async function loadWithConcurrency(items, concurrency, worker) {
  const queue = [...items];
  const runners = Array.from({ length: Math.min(concurrency, items.length) }, async () => {
    while (queue.length) {
      const item = queue.shift();
      if (!item) break;
      await worker(item);
    }
  });
  await Promise.all(runners);
}

function updateProgress(loaded, total) {
  const percent = total ? (loaded / total) * 100 : 0;
  dom.loadingStatus.textContent = `Preparing room models: ${loaded} / ${total}`;
  dom.progressBar.style.width = `${percent}%`;
}

const monitorScreens = {};

function initMonitorScreens() {
  for (const key of ["left_monitor_screen", "right_monitor_screen"]) {
    const obj = state.assetObjects.get(key);
    if (!obj) continue;
    const canvas = document.createElement("canvas");
    canvas.width = 512;
    canvas.height = 320;
    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.flipY = false;
    // Left monitor GLB UV is rotated 180° — correct it here
    if (key === "left_monitor_screen") {
      texture.center.set(0.5, 0.5);
      texture.rotation = Math.PI;
    }
    monitorScreens[key] = { canvas, ctx: canvas.getContext("2d"), texture };
    obj.traverse((mesh) => {
      if (!mesh.isMesh) return;
      mesh.material = new THREE.MeshStandardMaterial({
        map: texture,
        emissiveMap: texture,
        emissive: new THREE.Color(0xffffff),
        emissiveIntensity: 0.75,
        roughness: 0.25,
      });
    });
  }
  updateMonitorScreens();
}

function updateMonitorScreens() {
  if (!state.monitorOn) return;
  const now = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

  const left = monitorScreens.left_monitor_screen;
  if (left) {
    const { ctx, canvas, texture } = left;
    const g = ctx.createLinearGradient(0, 0, canvas.width, canvas.height);
    g.addColorStop(0, "#0b132b");
    g.addColorStop(1, "#1c2541");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#5bc0be";
    ctx.font = "bold 20px Inter, sans-serif";
    ctx.fillText("ALTA STUDY HUB", 28, 44);
    ctx.fillStyle = "rgba(255,255,255,0.7)";
    ctx.fillText(now, 385, 44);
    ctx.fillStyle = "#ffffff";
    ctx.font = "bold 70px monospace";
    ctx.fillText(formatTime(state.appData.pomodoro.remaining), 28, 155);
    ctx.fillStyle = "#94a3b8";
    ctx.font = "19px Inter, sans-serif";
    ctx.fillText(state.appData.pomodoro.embedUrl ? "▶ YouTube Video Ready" : "Click to play YouTube & Timer", 28, 218);
    ctx.fillStyle = "#38bdf8";
    ctx.fillRect(28, 255, 430, 8);
    texture.needsUpdate = true;
  }

  const right = monitorScreens.right_monitor_screen;
  if (right) {
    const { ctx, canvas, texture } = right;
    const g = ctx.createLinearGradient(0, 0, canvas.width, canvas.height);
    g.addColorStop(0, "#120c29");
    g.addColorStop(1, "#1e1b4b");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#a78bfa";
    ctx.font = "bold 20px Inter, sans-serif";
    ctx.fillText("ALTA AI TUTOR", 28, 44);
    ctx.fillStyle = "#34d399";
    ctx.font = "15px Inter, sans-serif";
    ctx.fillText("● LIVE AI", 315, 44);
    const last = [...state.appData.tutor.history].reverse().find((m) => m.role === "assistant")?.content
      || "Click monitor or headset to ask any question.";
    ctx.fillStyle = "#e2e8f0";
    ctx.font = "20px Inter, sans-serif";
    const words = last.slice(0, 95).split(" ");
    let line = "", y = 112;
    for (const w of words) {
      if ((line + w).length > 28) { ctx.fillText(line, 28, y); line = w + " "; y += 30; if (y > 245) break; }
      else line += w + " ";
    }
    if (line && y <= 245) ctx.fillText(line, 28, y);
    texture.needsUpdate = true;
  }
}

function finalizeRoomSetup() {
  const rawBounds = new THREE.Box3().setFromObject(state.roomRoot);
  const rawSize = rawBounds.getSize(new THREE.Vector3());
  const maxDim = Math.max(rawSize.x, rawSize.y, rawSize.z);

  if (maxDim > 0) {
    const scale = 10 / maxDim;
    state.roomRoot.scale.setScalar(scale);
    state.roomRoot.updateMatrixWorld(true);

    const scaledBounds = new THREE.Box3().setFromObject(state.roomRoot);
    const scaledCenter = scaledBounds.getCenter(new THREE.Vector3());
    state.roomRoot.position.set(-scaledCenter.x, -scaledBounds.min.y, -scaledCenter.z);
    state.roomRoot.updateMatrixWorld(true);
  }

  state.roomBounds = new THREE.Box3().setFromObject(state.roomRoot);
  state.roomBounds.getCenter(state.roomCenter);

  const ceiling = state.assetObjects.get("top");
  const door = state.assetObjects.get("door");
  if (ceiling && door) {
    const roomPlanes = new THREE.Box3().setFromObject(ceiling);
    const doorPlanes = new THREE.Box3().setFromObject(door);
    const paddedDoorEdge = doorPlanes.min.x - Math.max(0.2, state.camera.near * 3);
    const cameraPresets = state.sceneConfig.cameraPresets;
    const indoorPresetPositions = Object.entries(cameraPresets)
      .filter(([view, preset]) => view !== "door" && preset.position[0] <= paddedDoorEdge)
      .map(([, preset]) => new THREE.Vector3().fromArray(preset.position));
    const indoorPresetTargets = Object.entries(cameraPresets)
      .filter(([view, preset]) => view !== "door" && preset.target[0] <= paddedDoorEdge)
      .map(([, preset]) => new THREE.Vector3().fromArray(preset.target));
    const primaryRoom = indoorPresetPositions.length ? new THREE.Box3().setFromPoints(indoorPresetPositions) : roomPlanes.clone();
    const primaryTargets = indoorPresetTargets.length ? new THREE.Box3().setFromPoints(indoorPresetTargets) : roomPlanes.clone();
    const minY = Math.max(0.2, primaryTargets.min.y - 0.6);
    const maxY = Math.max(minY + 0.6, Math.min(roomPlanes.min.y, primaryRoom.max.y + 0.6));
    state.indoorBounds = new THREE.Box3(
      new THREE.Vector3(Math.min(roomPlanes.min.x, primaryRoom.min.x), minY, Math.min(roomPlanes.min.z, primaryRoom.min.z)),
      new THREE.Vector3(Math.min(roomPlanes.max.x, paddedDoorEdge), maxY, Math.max(roomPlanes.max.z, primaryRoom.max.z)),
    );
  }
  if (!state.indoorBounds) throw new Error("Main room geometry unavailable");

  const size = state.roomBounds.getSize(new THREE.Vector3());
  state.controls.maxDistance = Math.max(size.x, size.z) * 1.1;

  const lightProxy = createChandelierHitProxy(state.assetObjects.get("light"));
  if (lightProxy) {
    state.scene.add(lightProxy);
    state.interactiveMeshes.push(lightProxy);
  }

  initMonitorScreens();
  jumpCamera("door", true, true);
  resetDoorClosed();
  updateEntryControls();

  setTimeout(() => { dom.loadingOverlay.classList.add("hidden"); }, 250);
}

function startLoop(updateEditor) {
  const clock = new THREE.Clock();

  const render = () => {
    requestAnimationFrame(render);

    const delta = clock.getDelta();
    updateCameraTween();
    state.controls.update(delta);
    clampCameraToRoom();
    if (!state.editorOpen) state.doorMixer?.update(delta);
    if (!state.editorOpen) state.bookMixer?.update(delta);
    updatePropPulse();
    updateRecenterButton();
    state.catCompanion?.update(delta);
    updateEditor(delta);
    state.renderer.render(state.scene, state.camera);
    updateMonitorVideoOverlay();
  };

  render();
}

function updateCameraTween() {
  if (!state.cameraTween) return;
  const { startTime, duration, fromPos, toPos, fromTarget, toTarget, onComplete } = state.cameraTween;
  const elapsed = performance.now() - startTime;
  const t = Math.min(elapsed / duration, 1);
  const eased = 1 - Math.pow(1 - t, 3);
  state.camera.position.lerpVectors(fromPos, toPos, eased);
  state.controls.target.lerpVectors(fromTarget, toTarget, eased);
  if (t >= 1) {
    state.cameraTween = null;
    onComplete?.();
  }
}

function clampCameraToRoom() {
  if (!state.indoorBounds || state.editorOpen || !state.entered || state.entering) return;
  state.indoorBounds.clampPoint(state.controls.target, state.controls.target);
  state.indoorBounds.clampPoint(state.camera.position, state.camera.position);
  state.camera.lookAt(state.controls.target);
}

function onResize() {
  state.camera.aspect = window.innerWidth / window.innerHeight;
  state.camera.updateProjectionMatrix();
  state.renderer.setSize(window.innerWidth, window.innerHeight);
  state.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
}

function onPointerMove(event) {
  if (state.dragStart && state.activePointers.size && Math.hypot(event.clientX - state.dragStart.x, event.clientY - state.dragStart.y) > 6) {
    state.dragStart.moved = true;
  }
  if (event.type === "pointermove" && (event.pointerType === "touch" || state.activePointers.size || state.entering || state.editorOpen)) return;
  const rect = dom.canvas.getBoundingClientRect();
  state.pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  state.pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  updateHoverState();
}

function updateHoverState() {
  if (!state.interactiveMeshes.length) return;
  state.catCompanion?.refreshHitBounds();
  state.raycaster.setFromCamera(state.pointer, state.camera);
  const candidates = !state.entered && !state.editorOpen
    ? state.interactiveMeshes.filter(mesh => mesh.userData.assetName === "door")
    : state.interactiveMeshes;
  const intersects = state.raycaster.intersectObjects(candidates, false);
  const hit = intersects.find(item => item.object.userData.assetName !== "table" && !item.object.userData.isHitProxy) || intersects[0];

  if (!hit) { clearHoverState(); return; }
  const assetName = hit.object.userData.assetName;
  const interactive = resolveInteractiveMeta(assetName);
  if (!interactive) { clearHoverState(); return; }

  if (state.hoveredAsset !== assetName) {
    state.hoveredAsset = assetName;
    highlightAsset(assetName);
  }
  dom.canvas.style.cursor = "pointer";
}

function clearHoverState() {
  state.hoveredAsset = null;
  dom.canvas.style.cursor = "default";
  clearHighlight();
}

function highlightAsset(assetName) {
  if (state.highlightedAsset === assetName) return;
  clearHighlight();
  const roots = getHighlightRoots(assetName);
  if (!roots.length) return;

  state.highlightedAsset = assetName;
  roots.forEach((root) => {
    root.traverse((child) => {
      if (!child.isMesh || !child.material || child.userData.isHitProxy) return;
      const materials = Array.isArray(child.material) ? child.material : [child.material];
      materials.forEach((material) => {
        if (!material || material.userData.altaHighlighted) return;
        material.userData.altaSnapshot = {
          emissive: material.emissive?.clone?.() ?? null,
          emissiveIntensity: material.emissiveIntensity ?? 1,
          color: material.color?.clone?.() ?? null,
        };
        material.userData.altaHighlighted = true;
        if (material.emissive) {
          material.emissive.lerp(new THREE.Color(0x8a7dff), 0.7);
          material.emissiveIntensity = Math.max(material.userData.altaSnapshot.emissiveIntensity, 1.8);
        } else if (material.color) {
          material.color.offsetHSL(0.02, 0.1, 0.16);
        }
        state.highlightedMaterials.push(material);
      });
    });
  });
}

function clearHighlight() {
  state.highlightedMaterials.forEach((material) => {
    const snapshot = material.userData.altaSnapshot;
    if (!snapshot) return;
    if (material.emissive && snapshot.emissive) {
      material.emissive.copy(snapshot.emissive);
      material.emissiveIntensity = snapshot.emissiveIntensity;
    }
    if (material.color && snapshot.color) material.color.copy(snapshot.color);
    material.userData.altaHighlighted = false;
  });
  state.highlightedMaterials = [];
  state.highlightedAsset = null;
}

function onSceneClick(event) {
  const start = state.dragStart;
  state.dragStart = null;
  if (!start || start.moved || state.entering || state.editorOpen) return;
  if (Math.hypot(event.clientX - start.x, event.clientY - start.y) > 6) return;

  onPointerMove(event);
  const name = state.hoveredAsset;
  const target = resolveInteractiveMeta(name);
  if (event.pointerType === "touch" || event.sourceCapabilities?.firesTouchEvents) clearHoverState();
  if (!target) return;
  if (target.action === "cat") {
    if (state.catCompanion) state.catCompanion.pet();
    else playSound("cat");
    return;
  }
  if (target?.entry) { enterRoom(); return; }
  if (target?.exit) { exitRoom(); return; }
  if (target?.lighting) { playSound("button"); toggleLightingPopover(true); return; }
  if (target?.keyboard) { playSound("button"); handleKeyboardPropClick(); return; }
  if (target?.mouse) { handleMousePropClick(); return; }
  if (target?.action) {
    playSound("button");
    if (target.action === "mic") toggleMicrophone();
    if (target.action === "monitor") toggleMonitorPower();
    if (target.action === "wires") { pulseProp(name); showToast("Desk wires • connected"); }
    return;
  }
  if (state.posters.has(name)) { playSound("button"); focusPoster(name); return; }

  if (name === "book") playBook();
  playSound("button");
  if (target.view) jumpCamera(target.view);
  if (target.panel) openPanel(target.panel);
}

function openPanel(panelKey) {
  toggleLightingPopover(false);
  state.currentPanel = panelKey;
  const meta = PANEL_META[panelKey];
  dom.panelEyebrow.textContent = meta.eyebrow;
  dom.panelTitle.textContent = meta.title;
  dom.panelSubtitle.textContent = meta.subtitle;
  dom.panelBackdrop.classList.remove("hidden");
  dom.sidePanel.classList.add("open");
  dom.sidePanel.setAttribute("aria-hidden", "false");
  renderCurrentPanel();
}

function closePanel() {
  state.currentPanel = null;
  dom.panelBackdrop.classList.add("hidden");
  dom.sidePanel.classList.remove("open");
  dom.sidePanel.setAttribute("aria-hidden", "true");
}

function renderWelcome() {
  dom.panelContent.innerHTML = `<div class="card-stack"><section class="module-card"><h3>Welcome to ALTA</h3><p>Click any desk object to start studying.</p></section></div>`;
}

function renderCurrentPanel() {
  if (studyTools.render(state.currentPanel)) return;
  switch (state.currentPanel) {
    case "tutor": renderTutorPanel(); break;
    case "pomodoro": renderPomodoroPanel(); break;
    case "notebook": renderNotebookPanel(); break;
    case "calendar": renderCalendarPanel(); break;
    case "resources": renderResourcesPanel(); break;
    case "audio": renderAudioPanel(); break;
    case "break": renderBreakPanel(); break;
    default: renderWelcome();
  }
