function renderCalendarGrid(displayDate) {
  const year = displayDate.getFullYear();
  const month = displayDate.getMonth();
  const first = new Date(year, month, 1);
  const last = new Date(year, month + 1, 0);
  const todayKey = formatDateKey(new Date());
  const checkins = new Set(state.appData.calendar.checkins);
  const cells = DAYS.map((day) => `<div class="calendar-label">${day}</div>`);
  for (let i = 0; i < first.getDay(); i += 1) cells.push(`<div class="calendar-day muted"></div>`);
  for (let day = 1; day <= last.getDate(); day += 1) {
    const key = formatDateKey(new Date(year, month, day));
    cells.push(`<button class="calendar-day ${checkins.has(key) ? "done" : ""} ${key === todayKey ? "today" : ""}" data-action="calendar-toggle" data-date="${key}">${day}</button>`);
  }
  return cells.join("");
}

