function handlePanelClick(event) {
  const actionEl = event.target.closest("[data-action]");
  if (!actionEl) return;
  if (studyTools.click(actionEl)) return;
  const { action } = actionEl.dataset;

  switch (action) {
    case "tutor-send": sendTutorMessage(); break;
    case "tutor-stop": stopTutorStream(); break;
    case "tutor-clear": clearTutorHistory(); break;
    case "tutor-voice": toggleMicrophone(); break;
    case "tutor-quiz-notes":
      sendTutorMessage("Create 3 quick multiple-choice quiz questions based on my active study notes/document. Wait for my answers before revealing solutions.");
      break;
    case "monitor-load-url": {
      const raw = document.getElementById("monitorUrlInput")?.value || "";
      state.appData.pomodoro.embedUrl = raw.trim();
      state.appData.pomodoro.embedInput = raw.trim();
      storage.save("monitor-embed-url", state.appData.pomodoro.embedUrl);
      syncMonitorVideoFrame();
      updateMonitorScreens();
      if (convertToEmbedUrl(raw)) {
        closePanel();
        jumpCamera("desk");
        showToast("Playing video on Left 3D Monitor!");
