    case "monitor-clear-url":
      state.appData.pomodoro.embedUrl = "";
      state.appData.pomodoro.embedInput = "";
      storage.save("monitor-embed-url", "");
      syncMonitorVideoFrame();
      renderPomodoroPanel();
      updateMonitorScreens();
      break;
    case "pomodoro-start": startPomodoro(); break;
    case "pomodoro-pause": pausePomodoro(); break;
    case "pomodoro-reset": resetPomodoro(); break;
    case "pomodoro-preset": setPomodoroPreset(actionEl.dataset.mode, Number(actionEl.dataset.minutes)); break;
    case "todo-add": addTodo(); break;
    case "todo-delete": deleteTodo(actionEl.dataset.id); break;
    case "calendar-check-today": toggleCheckin(formatDateKey(new Date()), true); break;
    case "calendar-toggle": toggleCheckin(actionEl.dataset.date); break;
    case "calendar-prev": shiftCalendar(-1); break;
    case "calendar-next": shiftCalendar(1); break;
