async function sendTutorMessage(customPrompt) {
  const tutor = state.appData.tutor;
  const prompt = (typeof customPrompt === "string" ? customPrompt : tutor.draft).trim();
  if (!prompt || tutor.streaming) return;

  tutor.history.push({ role: "user", content: prompt });
  tutor.history.push({ role: "assistant", content: "Thinking..." });
  if (typeof customPrompt !== "string") tutor.draft = "";
  tutor.streaming = true;
  tutor.status = "Thinking...";
  renderTutorPanel();
  updateMonitorScreens();

  tutor.abortController = new AbortController();
  try {
    const { reply, provider } = await askStudyAI({
      history: tutor.history.slice(0, -1),
      studyContext: getActiveStudyContext(),
      signal: tutor.abortController.signal,
    });
    tutor.history[tutor.history.length - 1] = { role: "assistant", content: reply };
    tutor.status = provider;
  } catch (error) {
    const message = error?.name === "AbortError" ? "Stopped." : error?.message || "AI request failed.";
    tutor.history[tutor.history.length - 1] = { role: "error", content: message };
    tutor.status = "Retry needed";
  } finally {
    tutor.streaming = false;
    tutor.abortController = null;
    persistTutorHistory();
    updateMonitorScreens();
    if (state.currentPanel === "tutor") renderTutorPanel();
  }
}

