function setPomodoroPreset(mode, minutes) {
  const pomo = state.appData.pomodoro;
  pomo.running = false;
  pomo.endAt = null;
  pomo.mode = mode;
  pomo.remaining = minutes * 60;
  updateMonitorScreens();
  renderIfOpen("pomodoro");
}
function tickPomodoro() {
  const pomo = state.appData.pomodoro;
  if (!pomo.running) return;
  pomo.remaining = getSecondsRemaining(pomo.endAt);
  if (pomo.remaining <= 0) {
    pomo.running = false;
    pomo.endAt = null;
    pomo.remaining = 0;
    if (pomo.mode === "focus") {
      pomo.sessions += 1;
      storage.save("pomodoro-sessions", pomo.sessions);
    }
    updateHud();
  }
  updateMonitorScreens();
  renderIfOpen("pomodoro");
}

