function getDisplayDate() { return new Date(state.appData.calendar.displayYear, state.appData.calendar.displayMonth, 1); }
function shiftCalendar(direction) {
  const calendar = state.appData.calendar;
  calendar.displayMonth += direction;
  if (calendar.displayMonth < 0) { calendar.displayMonth = 11; calendar.displayYear -= 1; }
  else if (calendar.displayMonth > 11) { calendar.displayMonth = 0; calendar.displayYear += 1; }
  renderCalendarPanel();
}
function toggleCheckin(dateKey, forceOn = false) {
  const checkins = new Set(state.appData.calendar.checkins);
  if (forceOn) checkins.add(dateKey);
  else if (checkins.has(dateKey)) checkins.delete(dateKey);
  else checkins.add(dateKey);
  state.appData.calendar.checkins = [...checkins].sort();
  storage.save("calendar-checkins", state.appData.calendar.checkins);
  updateHud();
  renderCalendarPanel();
}
