function updateHud() { updateRecenterButton(); }
function updateRecenterButton() {
  const full = state.sceneConfig?.cameraPresets.full;
  if (!full || !state.entered || state.entering || state.editorOpen || state.currentPanel || !dom.lightingPopover.classList.contains("hidden")) {
    dom.backToRoom.hidden = true;
    return;
  }
  const { min, max } = state.indoorBounds;
  const differs = (vector, preset) => ["x", "y", "z"].some((axis, i) =>
    Math.abs(vector[axis] - THREE.MathUtils.clamp(preset[i], min[axis], max[axis])) > 0.08);
  dom.backToRoom.hidden = !state.focus && !differs(state.camera.position, full.position) && !differs(state.controls.target, full.target);
}

function jumpCamera(view, immediate = false, bypassLock = false, onComplete) {
  if (!state.roomBounds) return;
  if (!state.entered && !state.editorOpen && !bypassLock && view !== "door") return;
  state.focus = ["desk", "shelf", "cat"].includes(view) && (state.entered || state.editorOpen) ? view : null;

  const target = new THREE.Vector3();
  const position = new THREE.Vector3();
  const size = state.roomBounds.getSize(new THREE.Vector3());
  const dirTowardCenter = (anchor) => {
    const dir = new THREE.Vector3().subVectors(state.roomCenter, anchor);
    dir.y = 0;
    return dir.lengthSq() > 0.01 ? dir.normalize() : new THREE.Vector3(0, 0, 1);
  };

  const saved = state.sceneConfig.cameraPresets[view];
  if (saved) {
    position.fromArray(saved.position);
    target.fromArray(saved.target);
  } else if (view === "desk") {
    const anchor = getAssetWorldPosition("left_monitor") || getAssetWorldPosition("right_monitor") || getAssetWorldPosition("table") || state.roomCenter;
    const inward = dirTowardCenter(anchor);
    target.copy(anchor);
    position.copy(anchor).addScaledVector(inward, 2.2).add(new THREE.Vector3(0, 0.55, 0));
  } else if (view === "shelf") {
    const anchor = getAssetWorldPosition("bookstand") || getAssetWorldPosition("books") || state.roomCenter;
    const inward = dirTowardCenter(anchor);
    target.copy(anchor);
    position.copy(anchor).addScaledVector(inward, 2.4).add(new THREE.Vector3(0, 0.45, 0));
  } else if (view === "cat" || view === "door") {
    const anchor = getAssetWorldPosition(view) || state.roomCenter;
    const inward = dirTowardCenter(anchor);
    target.copy(anchor);
    position.copy(anchor).addScaledVector(inward, 1.7).add(new THREE.Vector3(0, 0.55, 0));
  } else {
    const deskAnchor = getAssetWorldPosition("table") || state.roomCenter;
    const inward = dirTowardCenter(deskAnchor);
    target.copy(state.roomCenter);
    position.copy(state.roomCenter).addScaledVector(inward, Math.max(size.x, size.z) * 0.34).add(new THREE.Vector3(0, size.y * 0.25, 0));
  }

  if (immediate) {
    state.cameraTween = null;
    state.camera.position.copy(position);
    state.controls.target.copy(target);
    state.controls.update();
    return;
  }
  tweenCamera(position, target, 850, onComplete);
}

function tweenCamera(position, target, duration = 850, onComplete) {
  state.cameraTween = {
    startTime: performance.now(), duration,
    fromPos: state.camera.position.clone(), toPos: position,
    fromTarget: state.controls.target.clone(), toTarget: target, onComplete,
  };
}

function updateEntryControls() {
  state.controls.enabled = state.editorOpen || (state.entered && !state.entering);
  updateRecenterButton();
}

function resolveInteractiveMeta(assetName) {
  if (!assetName) return null;
  if (assetName === "door") return state.entered ? { label: "Exit Study Room", exit: true } : { label: "Enter Study Room", entry: true };
  if (assetName === "keyboard") return { label: "3D Keyboard", keyboard: true };
  if (assetName === "mouse") return { label: "3D Mouse", mouse: true };
  if (INTERACTIVE_ASSETS[assetName]) return INTERACTIVE_ASSETS[assetName];
  if (state.posters.has(assetName)) return { label: `Inspect ${assetName.replaceAll("_", " ")}` };
  return null;
}

function getHighlightRoots(assetName) {
  if (assetName === "keyboard") return [...state.assetObjects.entries()].filter(([key]) => isKeyboardAsset(key)).map(([, obj]) => obj);
  if (assetName === "mouse") return [...state.assetObjects.entries()].filter(([key]) => isMouseAsset(key)).map(([, obj]) => obj);
  const single = state.assetObjects.get(assetName);
  return single ? [single] : [];
}

function initLightingPopover() {
  if (!dom.themePresetGrid) return;
  dom.themePresetGrid.innerHTML = Object.values(LIGHTING_THEMES).map(theme => `<button type="button" class="theme-preset-btn" data-theme-id="${theme.id}"><strong>${escapeHTML(theme.label)}</strong><span>${escapeHTML(theme.subtitle)}</span></button>`).join("");
  dom.themePresetGrid.addEventListener("click", (event) => { const btn = event.target.closest("[data-theme-id]"); if (btn) selectLightingTheme(btn.dataset.themeId); });
  dom.ceilingLightPower.addEventListener("click", () => { state.lightingSettings.ceilingEnabled = !state.lightingSettings.ceilingEnabled; saveLightingSettings(); applySceneLighting(); });
  dom.ceilingColorInput.addEventListener("input", () => { state.lightingSettings.ceilingColor = dom.ceilingColorInput.value; state.lightingSettings.custom = true; saveLightingSettings(); applySceneLighting(); });
  dom.ceilingIntensityInput.addEventListener("input", () => {
    const val = Number(dom.ceilingIntensityInput.value);
    state.lightingSettings.ceilingIntensity = val;
    state.lightingSettings.ceilingEnabled = val > 0;
    state.lightingSettings.custom = true;
    state.sceneConfig.lighting.ceilingIntensity = val;
    saveLightingSettings();
    applySceneLighting();
  });
  document.getElementById("saveLighting").addEventListener("click", () => {
    const saved = saveLightingSettings();
    const status = document.getElementById("lightingSaved");
    status.textContent = saved ? "Lighting saved" : "Could not save lighting";
    status.hidden = false;
  });
  selectLightingTheme(state.lightingSettings.themeId, false);
}

function selectLightingTheme(themeId, resetCustom = true) {
  const theme = LIGHTING_THEMES[themeId] || LIGHTING_THEMES.cozy;
  state.lightingSettings.themeId = theme.id;
  if (resetCustom || !state.lightingSettings.custom) {
    state.lightingSettings.custom = false;
    state.lightingSettings.label = theme.label;
    state.lightingSettings.ceilingColor = theme.ceilingColor;
    state.lightingSettings.ceilingIntensity = theme.ceilingIntensity;
    state.lightingSettings.ceilingEnabled = theme.ceilingEnabled;
  }
  if (resetCustom) {
    state.sceneConfig.lighting.toneMappingExposure = theme.exposure;
    state.sceneConfig.lighting.ambientIntensity = theme.ambientIntensity;
  }
  state.sceneConfig.lighting.ceilingIntensity = state.lightingSettings.ceilingIntensity;
  saveLightingSettings();
  applySceneLighting();
}

function saveLightingSettings() {
  try { storage.save("lighting-theme", state.lightingSettings); storage.save("scene-config", state.sceneConfig); return true; }
  catch { return false; }
}

function updateLightingUi() {
  const settings = state.lightingSettings;
  if (dom.themePresetGrid) for (const btn of dom.themePresetGrid.querySelectorAll("[data-theme-id]")) btn.classList.toggle("active", btn.dataset.themeId === settings.themeId && !settings.custom);
  if (dom.ceilingLightPower) { dom.ceilingLightPower.classList.toggle("active", settings.ceilingEnabled); dom.ceilingLightPower.textContent = settings.ceilingEnabled ? "On" : "Off"; }
  if (dom.ceilingColorInput) dom.ceilingColorInput.value = settings.ceilingColor;
  if (dom.ceilingIntensityInput) dom.ceilingIntensityInput.value = String(state.sceneConfig.lighting.ceilingIntensity);
  if (dom.ceilingIntensityOutput) dom.ceilingIntensityOutput.textContent = String(Math.round(state.sceneConfig.lighting.ceilingIntensity * 10) / 10);
}

function toggleLightingPopover(force) {
  if (!dom.lightingPopover) return;
  const willOpen = typeof force === "boolean" ? force : dom.lightingPopover.classList.contains("hidden");
  if (willOpen && state.currentPanel) closePanel();
  dom.lightingPopover.classList.toggle("hidden", !willOpen);
  if (willOpen) updateLightingUi();
}

function handleKeyboardPropClick() {
  if (state.focus !== "desk") jumpCamera("desk");
  const targetPanel = state.currentPanel === "tutor" ? "tutor" : "notebook";
  openPanel(targetPanel);
  pulseKeyboardVisual("space");
}

function pulseKeyboardVisual(key) {
  const lower = String(key || "").toLowerCase();
  const keyAsset = state.assetObjects.get(lower === " " ? "space" : lower) || state.assetObjects.get("keyboard_without_keys");
  if (!keyAsset) return;
  if (keyAsset.userData.baseY === undefined) keyAsset.userData.baseY = keyAsset.position.y;
  keyAsset.position.y = keyAsset.userData.baseY - 1.1;
  window.setTimeout(() => { keyAsset.position.y = keyAsset.userData.baseY; }, 95);
}

function handleMousePropClick() {
  playSound("mouse");
  getHighlightRoots("mouse").forEach((root) => {
    if (root.userData.baseY === undefined) root.userData.baseY = root.position.y;
    root.position.y = root.userData.baseY - 1.35;
    window.setTimeout(() => { root.position.y = root.userData.baseY; }, 120);
  });
}

function doorAction() {
  const entry = state.animatedAssets.get("door");
  const clip = entry?.animations.find(item => /open/i.test(item.name)) || entry?.animations[0];
  if (!clip) return null;
  state.doorMixer ??= new THREE.AnimationMixer(entry.root);
  state.doorClip ??= THREE.AnimationUtils.subclip(clip, "ALTA door opening", 0, Math.min(77, Math.floor(clip.duration * 24)), 24);
  const action = state.doorMixer.clipAction(state.doorClip);
  action.reset().setLoop(THREE.LoopOnce, 1);
  action.clampWhenFinished = true;
  return action;
}

function resetDoorClosed() {
  const action = doorAction();
  if (!action) return;
  action.paused = true;
  action.play();
  state.doorMixer.update(0);
}

function playDoor(open, done) {
  if (state.doorFinished) state.doorMixer.removeEventListener("finished", state.doorFinished);
  const action = doorAction();
  if (!action) { done(); return; }
  if (!open) action.time = action.getClip().duration;
  const finished = event => {
    if (event.action !== action) return;
    state.doorMixer.removeEventListener("finished", finished);
    state.doorFinished = null;
    queueMicrotask(() => { if (state.entering && !state.editorOpen) done(); });
  };
  state.doorFinished = finished;
  state.doorMixer.addEventListener("finished", finished);
  action.setEffectiveTimeScale(open ? 2.5 : -2.5).play();
}

function enterRoom() { if (!state.entered) crossDoor(true); }
function exitRoom() { if (state.entered) crossDoor(false); }
function crossDoor(enteringRoom) {
  if (state.entering || state.editorOpen) return;
  state.entering = true;
  clearHoverState();
  closePanel();
  toggleLightingPopover(false);
  updateEntryControls();
  playSound("door");
  playDoor(true, () => jumpCamera(enteringRoom ? "full" : "door", false, true, () => {
    state.entered = enteringRoom;
    playDoor(false, () => { state.entering = false; updateEntryControls(); });
  }));
}

function backToRoom() { closePanel(); jumpCamera("full"); }
function focusPoster(name) {
  const root = state.assetObjects.get(name);
  if (!root) return;
  const interior = getAssetWorldPosition("table") || state.roomCenter;
  const blockers = [...state.assetObjects.entries()].filter(([key]) => key !== name && key !== "walls" && key !== "floor" && key !== "top" && !state.posters.has(key)).map(([, object]) => object);
  const { position, target } = posterView(root, interior, state.camera, blockers);
  state.focus = `poster:${name}`;
  dom.backToRoom.hidden = false;
  closePanel();
  tweenCamera(position, target);
}

function getAssetWorldPosition(assetName) {
  const object = state.assetObjects.get(assetName);
  if (!object) return null;
  const position = new THREE.Vector3();
  new THREE.Box3().setFromObject(object).getCenter(position);
  return position;
}

function renderIfOpen(panelKey) { if (state.currentPanel === panelKey) renderCurrentPanel(); }
function getCurrentStreak() {
  const dates = [...state.appData.calendar.checkins].sort();
  if (!dates.length) return 0;
  const set = new Set(dates);
  let streak = 0;
  const cursor = new Date();
  cursor.setHours(0, 0, 0, 0);
  while (set.has(formatDateKey(cursor))) { streak += 1; cursor.setDate(cursor.getDate() - 1); }
  return streak;
}
function getBestStreak() {
  const dates = [...new Set(state.appData.calendar.checkins)].sort();
  if (!dates.length) return 0;
  let best = 1, current = 1;
  for (let i = 1; i < dates.length; i += 1) {
    const diffDays = (new Date(`${dates[i]}T00:00:00`) - new Date(`${dates[i - 1]}T00:00:00`)) / 86400000;
    current = diffDays === 1 ? current + 1 : 1;
    best = Math.max(best, current);
  }
  return best;
}
function presetSecondsForMode(mode) { return mode === "short" ? 300 : mode === "long" ? 900 : 1500; }
function labelPomodoroMode(mode) { return mode === "short" ? "Short break" : mode === "long" ? "Long reset" : "Focus block"; }
function getSecondsRemaining(endAt) { return Math.max(0, Math.ceil((endAt - Date.now()) / 1000)); }
function formatTime(totalSeconds) {
  const safe = Math.max(0, totalSeconds);
  return `${String(Math.floor(safe / 60)).padStart(2, "0")}:${String(safe % 60).padStart(2, "0")}`;
}
function formatDateKey(date) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; }
function randomFrom(array) { return array[Math.floor(Math.random() * array.length)]; }
function escapeHTML(value = "") { return String(value).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#39;"); }
function escapeAttribute(value = "") { return escapeHTML(value); }

