import { AnimationMixer, Box3, Group, Quaternion, Vector3, MathUtils } from "three";

const cat = suffix => `SKM_Cat|SKM_Cat|Cat_${suffix}`;
const WALKS = new Map([[cat("WalkSlow"), 35], [cat("Walk"), 50]]); // Authored units/s at 1×, from planted-paw travel.
const RESTS = [cat("Sit"), cat("Stand"), "SKM_Cat|AA_SKM_Cat|Cat_Ilde01", cat("Ilde02"), cat("Idle03"), cat("Idle04")];
const PETS = [cat("Sit"), cat("Idle03"), cat("Idle04")];
const ALLOWED = new Set([...WALKS.keys(), ...RESTS]);
const BLOCKED = new Set([cat("Death"), cat("Dash"), cat("Run"), cat("Trot")]);
const UP = new Vector3(0, 1, 0);
const FADE = 0.42;
const CLEARANCE = 77; // Measured animated footprint (max radius ~75 authored units).
const random = (min, max) => MathUtils.lerp(min, max, Math.random());
const pick = list => list[Math.floor(Math.random() * list.length)];

export function filterRoomClips(asset, clips) {
  return clips.filter(clip => asset === "cat" ? ALLOWED.has(clip.name) : !BLOCKED.has(clip.name));
}

// Segment vs. padded prop footprint: endpoints alone are not enough to prevent crossing a prop.
export function crossesFootprint(from, to, box) {
  let enter = 0;
  let exit = 1;
  for (const axis of ["x", "z"]) {
    const step = to[axis] - from[axis];
    if (Math.abs(step) < 1e-6) {
      if (from[axis] < box.min[axis] || from[axis] > box.max[axis]) return false;
    } else {
      const a = (box.min[axis] - from[axis]) / step;
      const b = (box.max[axis] - from[axis]) / step;
      enter = Math.max(enter, Math.min(a, b));
      exit = Math.min(exit, Math.max(a, b));
      if (enter > exit) return false;
    }
  }
  return true;
}

export function createCatCompanion({ entry, assets, camera, sound, ambientEnabled, sfxVolume = () => 1 }) {
  if (!entry) return null;
  const { root, animations } = entry;
  const room = root.parent;
  const rig = root.getObjectByName("StudyShelf_1838");
  const mesh = root.getObjectByName("StudyShelf_1839");
  if (!room || !rig || !mesh) return null;

  // Retain the rig's authored pose. Rotate and translate around its floor anchor, not the GLB's scene origin.
  const origin = rig.position.clone();
  const pivot = new Group();
  pivot.position.copy(origin);
  pivot.position.x += 9; // Clear the chair-facing side of the authored spawn gap.
  pivot.position.y -= 4.2; // Measured paw height versus the main wooden floor surface.
  room.add(pivot);
  pivot.add(root);
  root.position.sub(origin);
  mesh.frustumCulled = false; // The static bounds don't represent the animated, skinned pose.

  const mixer = new AnimationMixer(root);
  const actions = new Map(animations.filter(clip => ALLOWED.has(clip.name)).map(clip => [clip.name, mixer.clipAction(clip)]));
  const rests = RESTS.filter(name => actions.has(name));
  const pets = PETS.filter(name => actions.has(name));
  const walk = [...WALKS.keys()].find(name => actions.has(name));
  const walkSpeed = WALKS.get(walk) || 0;
  // These main-room coordinates exclude the outer floor panel and all walls/doorway approaches.
  const bounds = { minX: origin.x - 107, maxX: origin.x + 13, minZ: origin.z, maxZ: origin.z + 267 };
  const obstacles = [];
  const toRoom = room.matrixWorld.clone().invert();
  for (const [name, object] of assets) {
    if (name === "floor" || name === "walls" || name === "cat") continue;
    const box = new Box3().setFromObject(object).applyMatrix4(toRoom);
    if (box.max.y < 15 || box.min.y > 100 || box.isEmpty()) continue;
    box.expandByScalar(CLEARANCE);
    if (box.max.x < bounds.minX || box.min.x > bounds.maxX || box.max.z < bounds.minZ || box.min.z > bounds.maxZ) continue;
    obstacles.push(box);
  }
  const waypoint = new Vector3();
  const direction = new Vector3();
  const cameraLocal = new Vector3();
  const facing = new Quaternion();
  const forwardYaw = Math.atan2(-0.52, -0.85); // Head-to-body forward from the authored walking pose.
  let mode = "rest";
  let until = random(4, 9);
  let elapsed = 0;
  let nextAmbient = random(45, 75);
  let lastSound = -Infinity;
  let testing = null;
  let active;
  let fadeAt;
  let speed = 0;

  function blend(name) {
    const next = actions.get(name);
    if (!next || next === active) return;
    const weights = new Map();
    for (const action of actions.values()) {
      if (action.isScheduled()) weights.set(action, action.getEffectiveWeight());
    }
    if (!next.isScheduled()) next.reset().setEffectiveWeight(active ? 0 : 1).play();
    fadeAt = { time: 0, weights };
    active = next;
  }

  function rest() {
    mode = "rest";
    speed = 0;
    until = elapsed + random(4, 9);
    blend(pick(rests));
  }

  function pickWaypoint() {
    if (!walk || !rests.length) return false;
    let best = 0;
    for (let attempt = 0; attempt < 28; attempt++) {
      const x = random(bounds.minX, bounds.maxX);
      const z = random(bounds.minZ, bounds.maxZ);
      const distance = Math.hypot(x - pivot.position.x, z - pivot.position.z);
      if (distance < 42 || distance > 140 || distance <= best) continue;
      const point = { x, z };
      if (obstacles.some(box => crossesFootprint(pivot.position, point, box))) continue;
      waypoint.set(x, pivot.position.y, z);
      best = distance;
    }
    // The spawn is in a narrow chair/door gap. Have a straight-ahead exit even if random samples miss it.
    if (!best && pivot.position.z < origin.z + 100) {
      const point = { x: pivot.position.x, z: pivot.position.z + 90 };
      if (!obstacles.some(box => crossesFootprint(pivot.position, point, box))) {
        waypoint.set(point.x, pivot.position.y, point.z);
        return true;
      }
    }
    return best > 0;
  }

  function turnToward(point, delta, rate) {
    direction.subVectors(point, pivot.position).setY(0);
    if (direction.lengthSq() < 0.001) return 0;
    facing.setFromAxisAngle(UP, Math.atan2(direction.x, direction.z) - forwardYaw);
    pivot.quaternion.rotateTowards(facing, delta * rate);
    return pivot.quaternion.angleTo(facing);
  }

  function meow(ambient) {
    if (elapsed - lastSound < 2.2 || !sound.paused || (ambient && !ambientEnabled())) return;
    lastSound = elapsed;
    sound.volume = (ambient ? 0.10 : 0.26) * sfxVolume();
    sound.currentTime = 0;
    sound.play().catch(() => {});
  }

  function pose(delta) {
    if (fadeAt) {
      fadeAt.time += delta;
      const t = MathUtils.smoothstep(fadeAt.time, 0, FADE);
      for (const action of actions.values()) {
        if (!action.isScheduled()) continue;
        action.setEffectiveWeight(MathUtils.lerp(fadeAt.weights.get(action) ?? 0, action === active ? 1 : 0, t));
        if (t === 1 && action !== active) action.stop();
      }
      if (t === 1) fadeAt = undefined;
    }
    mixer.update(delta);
    pivot.updateMatrixWorld(true);
  }

  rest();
  pose(0);
  console.info(`[ALTA] Cat companion ready (${actions.size} cozy clips, ${obstacles.length} nearby prop bounds)`);

  return {
    update(delta) {
      if (testing || delta <= 0) return;
      const dt = Math.min(delta, 0.075);
      elapsed += dt;
      if (mode === "pet") {
        turnToward(room.worldToLocal(camera.getWorldPosition(cameraLocal)), dt, 2.5);
        if (elapsed >= until) rest();
      } else if (mode === "rest" && elapsed >= until) {
        if (pickWaypoint()) mode = "turn";
        else until = elapsed + random(4, 9);
      }
      if (mode === "turn" && turnToward(waypoint, dt, 2.8) < 0.04) {
        mode = "walk";
        blend(walk);
      }
      if (mode === "walk") {
        direction.subVectors(waypoint, pivot.position);
        const remaining = direction.length();
        speed = Math.min(speed + 105 * dt, walkSpeed, Math.sqrt(2 * 105 * remaining));
        const step = Math.min(remaining, speed * dt);
        actions.get(walk).setEffectiveTimeScale(step / (walkSpeed * dt));
        if (remaining > 0) pivot.position.addScaledVector(direction, step / remaining);
        if (remaining - step < 0.02) rest();
      }
      if (elapsed >= nextAmbient && mode !== "pet") {
        nextAmbient = elapsed + random(45, 75);
        meow(true);
      }
      pose(dt);
    },
    pet() {
      if (testing) return;
      if (mode !== "pet") blend(pick(pets.length ? pets : rests));
      mode = "pet";
      speed = 0;
      until = elapsed + random(3, 5);
      meow(false);
    },
    pauseForTester(model) {
      if (testing === model) return;
      const wasTestingCat = testing === "cat";
      testing = model;
      if (model === "cat") {
        // Release the rig tracks before the manual mixer binds them.
        mixer.stopAllAction();
        active = fadeAt = undefined;
      } else if (wasTestingCat) {
        rest();
        pose(0);
      }
    },
    refreshHitBounds() {
      mesh.computeBoundingSphere();
    },
    muteAmbient() {
      if (sound.volume === 0.10) sound.pause();
    },
  };
}

