.alta-dev-editor:not([open]), .alta-dev-editor [hidden] { display: none !important; }
.alta-dev-editor {
  position: fixed; inset: auto 1rem 1rem auto; margin: 0; z-index: 60;
  width: min(30rem, calc(100vw - 2rem)); max-width: none;
  max-height: min(44rem, calc(100dvh - 2rem)); padding: 0;
  display: flex; flex-direction: column; color: #f4f2ff;
  background: rgba(17, 20, 33, .94); border: 1px solid #8c82db65; border-radius: 18px;
  backdrop-filter: blur(18px); box-shadow: 0 22px 70px #000a;
}
.alta-dev-editor header, .alta-dev-editor nav, .alta-dev-editor footer { padding: .8rem 1rem; }
.alta-dev-editor header { display: flex; justify-content: space-between; align-items: center; gap: .8rem; }
.alta-dev-editor small { color: #cabfff; font-size: .65rem; letter-spacing: .15em; }
.alta-dev-editor h2 { margin: .2rem 0 0; font-size: 1.1rem; }
.alta-dev-editor h3 { margin: 1rem 0 .45rem; font-size: .88rem; }
.alta-dev-editor p { margin: .25rem 0 .7rem; color: #c5c9df; font-size: .79rem; }
.alta-dev-editor nav { display: flex; gap: .45rem; border-block: 1px solid #ffffff18; }
.alta-dev-editor button, .alta-dev-editor select, .alta-dev-editor textarea {
  background: #26283e; color: inherit; border: 1px solid #ffffff28; border-radius: 7px;
  font: inherit; padding: .42rem .58rem; font-size: .76rem;
}
.alta-dev-editor button { cursor: pointer; }
.alta-dev-editor button:hover, .alta-dev-editor [aria-selected="true"] { background: #503d91; }
.alta-dev-editor :focus-visible { outline: 2px solid #c2aaff; outline-offset: 2px; }
.alta-dev-editor :disabled { opacity: .5; cursor: default; }
.alta-dev-content { overflow: auto; overscroll-behavior: contain; padding: .8rem 1rem; }
.alta-dev-editor pre { margin: 0; overflow: auto; padding: .65rem; border-radius: 7px; background: #0d1020; font-size: .72rem; color: #dfd5ff; }
.alta-dev-presets, .alta-dev-export-actions { display: grid; gap: .38rem; }
.alta-dev-presets > div { display: grid; grid-template-columns: 1fr auto auto; align-items: center; gap: .35rem; font-size: .79rem; }
.alta-dev-light, .alta-dev-select { display: grid; grid-template-columns: 8.6rem minmax(0, 1fr) 2.5rem; gap: .45rem; align-items: center; margin: .42rem 0; font-size: .78rem; }
.alta-dev-light output { text-align: right; font-variant-numeric: tabular-nums; }
.alta-dev-light input { width: 100%; accent-color: #ad92ff; }
.alta-dev-select { grid-template-columns: 3rem minmax(0, 1fr); }
.alta-dev-actions { display: flex; gap: .4rem; margin-top: .5rem; }
.alta-dev-editor textarea { width: 100%; min-height: 7rem; margin-top: .6rem; }
.alta-dev-editor footer { border-top: 1px solid #ffffff18; color: #d7ccff; font-size: .76rem; min-height: 2.65rem; }
@media (max-width: 620px) {
  .alta-dev-editor { inset: auto .5rem .5rem auto; width: calc(100vw - 1rem); max-height: 68dvh; }
}

sources.design/ATLA/dev-editor.js:
import { AnimationMixer, LoopOnce, LoopRepeat } from "three";
import { LIGHTS, VIEWS } from "./scene-config.js";
import "./dev-editor.css";

export function attachDevEditor({ camera, controls, clips, config, applyLighting, readLighting, save, jump, models, sounds, onAnimationTest, onOpenChange }) {
  let editor;
  let mixer;
  let activeRoot;
  let readout;
  let opener;
  let exporting = false;

  function stop(resumeCompanion = true) {
    if (!mixer) return;
    mixer.stopAllAction();
    mixer.uncacheRoot(activeRoot);
    activeRoot.updateMatrixWorld(true);
    mixer = activeRoot = undefined;
    if (resumeCompanion) onAnimationTest?.(null);
  }

  function syncLighting() {
    const values = readLighting();
    for (const input of editor.querySelectorAll("[data-light]")) {
      input.value = values[input.dataset.light];
      input.nextElementSibling.textContent = input.value;
    }
  }

  function buildEditor() {
    const dialog = document.createElement("dialog");
    dialog.className = "alta-dev-editor";
    dialog.setAttribute("aria-labelledby", "alta-dev-title");
    dialog.innerHTML = `
      <header><div><small>ALTA / CREATOR TOOLS</small><h2 id="alta-dev-title">Dev Editor &amp; Full Project Exporter</h2></div>
        <button type="button" data-act="close" aria-label="Close developer editor" autofocus>×</button></header>
      <nav role="tablist" aria-label="Developer tools">
        <button type="button" id="alta-dev-live-tab" role="tab" aria-controls="alta-dev-live" aria-selected="true" data-tab="live">Live Scene &amp; Camera</button>
        <button type="button" id="alta-dev-export-tab" role="tab" aria-controls="alta-dev-export" aria-selected="false" tabindex="-1" data-tab="export">Full Exporter</button>
      </nav>
      <div class="alta-dev-content">
        <section id="alta-dev-live" role="tabpanel" aria-labelledby="alta-dev-live-tab">
          <p>Orbit the room beside this panel. Capture saves the current view to this browser.</p>
          <pre data-readout aria-label="Live camera and target coordinates"></pre>
          <h3>Camera presets</h3>
          <div class="alta-dev-presets">${Object.entries(VIEWS).map(([key, name]) => `
            <div><span>${name}</span><button type="button" data-act="jump" data-view-key="${key}" aria-label="Jump to ${name}">Jump</button>
              <button type="button" data-act="capture" data-view-key="${key}" aria-label="Capture current view for ${name}">Capture Current View</button></div>`).join("")}</div>
          <h3>Lighting</h3>
          ${Object.entries(LIGHTS).map(([key, light]) => `<label class="alta-dev-light"><span>${light.label}</span>
            <input type="range" min="0" max="${light.max}" step="${light.step}" data-light="${key}" /><output></output></label>`).join("")}
          <h3>Animation tester</h3>
          <p>Stop or close the editor to restore the original pose.</p>
          <label class="alta-dev-select">Model<select data-model></select></label>
          <label class="alta-dev-select">Clip<select data-clip></select></label>
          <div class="alta-dev-actions"><button type="button" data-act="play">Play</button><button type="button" data-act="stop">Stop</button><button type="button" data-act="loop">Loop</button></div>
        </section>
        <section id="alta-dev-export" role="tabpanel" aria-labelledby="alta-dev-export-tab" hidden>
          <p>Export your camera and lighting separately, or download the GitHub Pages build and editable source together.</p>
          <div class="alta-dev-export-actions"><button type="button" data-act="config">Export Scene Config (scene-config.json)</button>
            <button type="button" data-act="copy">Copy Camera Presets JS</button><button type="button" data-act="zip">Export Full Project (.zip)</button></div>
          <textarea data-copy-fallback readonly aria-label="Camera presets JavaScript" hidden></textarea>
        </section>
      </div>
      <footer role="status"></footer>`;
    document.body.append(dialog);
    readout = dialog.querySelector("[data-readout]");
    const model = dialog.querySelector("[data-model]");
    const clip = dialog.querySelector("[data-clip]");
    const status = dialog.querySelector("footer");
    const report = text => { status.textContent = text; };
    for (const key of [...clips.keys()].sort()) model.add(new Option(`${key}.glb`, key));
    function refreshClips() {
      clip.replaceChildren();
      const entry = clips.get(model.value);
      entry?.animations.forEach((item, index) => clip.add(new Option(item.name || `Clip ${index + 1}`, index)));
      for (const button of dialog.querySelectorAll('[data-act="play"], [data-act="loop"], [data-act="stop"]')) button.disabled = !entry;
    }
    refreshClips();
    model.addEventListener("change", () => { stop(); refreshClips(); });
    clip.addEventListener("change", () => stop());
    function selectTab(tab, focus = false) {
      for (const button of dialog.querySelectorAll("[data-tab]")) {
        const selected = tab === button.dataset.tab;
        button.setAttribute("aria-selected", String(selected));
        button.tabIndex = selected ? 0 : -1;
        dialog.querySelector(`#alta-dev-${button.dataset.tab}`).hidden = !selected;
        if (selected && focus) button.focus();
      }
      if (tab === "live") syncLighting();
      else stop();
    }
    dialog.querySelector('[role="tablist"]').addEventListener("keydown", event => {
      if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key) || !event.target.dataset.tab) return;
      event.preventDefault();
      selectTab(event.key === "Home" ? "live" : event.key === "End" ? "export" : event.target.dataset.tab === "live" ? "export" : "live", true);
    });
    dialog.addEventListener("input", event => {
      const key = event.target.dataset.light;
      if (!key) return;
      config.lighting[key] = event.target.valueAsNumber;
      applyLighting(key);
      event.target.nextElementSibling.textContent = event.target.value;
    });
    dialog.addEventListener("change", event => {
      if (event.target.dataset.light) report(save() ? "Lighting saved." : "Lighting applied. Browser storage is unavailable.");
    });
    dialog.addEventListener("click", async event => {
      event.stopPropagation();
      const button = event.target.closest("button");
      if (!button) return;
      if (button.dataset.tab) return selectTab(button.dataset.tab);
      const { act, viewKey } = button.dataset;
      if (act === "close") return close();
      if (act === "jump") return jump(viewKey);
      if (act === "capture") {
        config.cameraPresets[viewKey] = { position: camera.position.toArray(), target: controls.target.toArray() };
        const saved = save();
        jump(viewKey, true);
        report(saved ? `${VIEWS[viewKey]} preset saved.` : `${VIEWS[viewKey]} updated. Browser storage is unavailable.`);
        console.info(`[ALTA] Captured ${viewKey} camera preset`);
      }
      if (act === "stop") { stop(); report("Animation stopped; original pose restored."); }
      if (act === "play" || act === "loop") {
        const entry = clips.get(model.value);
        const animation = entry?.animations[Number(clip.value)];
        if (!animation) return;
        stop(false);
        onAnimationTest?.(model.value);
        activeRoot = entry.root;
        const currentMixer = mixer = new AnimationMixer(activeRoot);
        currentMixer.addEventListener("finished", () => {
          // Restore after the mixer has finished applying this frame.
          queueMicrotask(() => {
            if (mixer !== currentMixer) return;
            stop();
            report("Animation finished; original pose restored.");
          });
        });
        mixer.clipAction(animation).setLoop(act === "loop" ? LoopRepeat : LoopOnce, act === "loop" ? Infinity : 1).play();
        report(`${act === "loop" ? "Looping" : "Playing"} ${animation.name || "clip"} on ${model.value}.glb.`);
      }
      if (act === "copy") {
        const text = `const cameraPresets = ${JSON.stringify(config.cameraPresets, null, 2)};`;
        const fallback = dialog.querySelector("[data-copy-fallback]");
        try {
          await navigator.clipboard.writeText(text);
          fallback.hidden = true;
          report("Camera presets copied as JavaScript.");
        } catch {
          fallback.hidden = false;
          fallback.value = text;
          fallback.focus();
          fallback.select();
          report("Clipboard blocked. Press Ctrl+C or Command+C to copy the selected code.");
        }
      }
      if (act === "zip" || act === "config") {
        if (act === "zip" && exporting) return;
        button.disabled = true;
        if (act === "zip") exporting = true;
        const snapshot = structuredClone(config);
        snapshot.lighting = readLighting();
        try {
          const { downloadFile, exportProject } = await import("./project-export.js");
          if (act === "config") downloadFile("scene-config.json", new Blob([JSON.stringify(snapshot, null, 2) + "\n"], { type: "application/json" }));
          else await exportProject(snapshot, models, sounds, report);
          report(act === "zip" ? "Full project ZIP downloaded." : "Scene config downloaded.");
          console.info(`[ALTA] ${act === "zip" ? "Project ZIP" : "Scene config"} exported`);
        } catch (error) {
          console.error("[ALTA] Export failed", error);
          report(`Export failed: ${error.message}`);
        } finally {
          button.disabled = false;
          if (act === "zip") exporting = false;
        }
      }
    });
    return dialog;
  }

  function close() {
    stop();
    editor.close();
    onOpenChange?.(false);
    if (opener instanceof HTMLElement && opener.isConnected) opener.focus({ preventScroll: true });
  }

  window.addEventListener("keydown", event => {
    const shortcut = event.ctrlKey && event.shiftKey && !event.altKey && !event.metaKey && (event.code === "KeyE" || event.key.toLowerCase() === "e");
    if (!shortcut && !(editor?.open && event.key === "Escape")) return;
    event.preventDefault();
    event.stopPropagation();
    if (event.repeat) return;
    if (editor?.open) return close();
    opener = document.activeElement;
    editor ??= buildEditor();
    editor.show();
    onOpenChange?.(true);
    syncLighting();
  }, true);

  return delta => {
    if (!editor?.open) return;
    mixer?.update(Math.min(delta, 0.1));
    const format = v => `${v.x.toFixed(4)}  ${v.y.toFixed(4)}  ${v.z.toFixed(4)}`;
    const text = `              x         y         z\nPosition  ${format(camera.position)}\nTarget    ${format(controls.target)}`;
    if (readout.textContent !== text) readout.textContent = text;
  };
}

