const KEYCAP_SINGLE = new Set([
  "a", "b", "c", "d", "e", "f", "g", "h", "i", "j", "k", "l", "m",
  "n", "o", "p", "q", "r", "s", "t", "u", "v", "w", "x", "y", "z",
]);

const KEYBOARD_ASSETS = new Set([
  "keyboard_without_keys",
  "capslock", "down_arrow", "enter", "esc", "fn", "key",
  "leftalt", "leftctrl", "leftshift", "left_arrow", "pause", "prtsc",
  "rightalt", "rightctrl", "rightshift", "right_arrow", "scrlk",
  "space", "tab", "up_arrow", "win", "winlk",
  "f1", "f2", "f3", "f4", "f5", "f6", "f7", "f8", "f9", "f10", "f11", "f12",
]);

const MOUSE_ASSETS = new Set([
  "mouse", "mousescroll", "mouse_left_right_click", "mouse_tiny_centre_button",
]);

export function isKeyboardAsset(assetName) {
  if (!assetName) return false;
  return KEYCAP_SINGLE.has(assetName) || KEYBOARD_ASSETS.has(assetName) || assetName.startsWith("key_");
}

export function isMouseAsset(assetName) {
  return MOUSE_ASSETS.has(assetName);
}

export function normalizeLightingSettings(saved) {
  const base = LIGHTING_THEMES[saved?.themeId] || LIGHTING_THEMES.cozy;
  const color = typeof saved?.ceilingColor === "string" && /^#[0-9a-f]{6}$/i.test(saved.ceilingColor)
    ? saved.ceilingColor
    : base.ceilingColor;
  const intensity = Number.isFinite(saved?.ceilingIntensity)
    ? THREE.MathUtils.clamp(saved.ceilingIntensity, 0, 60)
    : base.ceilingIntensity;
  const ceilingEnabled = typeof saved?.ceilingEnabled === "boolean" ? saved.ceilingEnabled : base.ceilingEnabled;
  return {
    themeId: base.id,
    label: saved?.custom ? "Custom" : base.label,
    custom: Boolean(saved?.custom),
    ceilingColor: color,
    ceilingIntensity: intensity,
    ceilingEnabled,
  };
}

export function createChandelierHitProxy(lightRoot) {
  if (!lightRoot) return null;
  const box = new THREE.Box3().setFromObject(lightRoot);
  if (box.isEmpty()) return null;
  const size = box.getSize(new THREE.Vector3());
  const center = box.getCenter(new THREE.Vector3());
  const radius = Math.max(size.x, size.z) * 0.62;
  const height = Math.max(size.y * 1.15, 0.35);
  const geometry = new THREE.CylinderGeometry(radius * 0.78, radius, height, 16);
  const material = new THREE.MeshBasicMaterial({
    transparent: true,
    opacity: 0,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  const proxy = new THREE.Mesh(geometry, material);
  proxy.name = "ALTA_ChandelierHitProxy";
  proxy.userData.assetName = "light";
  proxy.userData.isHitProxy = true;
  proxy.position.copy(center);
  return proxy;
}

