import JSZip from "jszip";

export function downloadFile(name, blob) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = name;
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

async function fetchFile(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`HTTP ${response.status}: ${url}`);
  return response;
}

export async function exportProject(config, models, sounds, progress) {
  const base = import.meta.env.BASE_URL;
  const pagesBase = import.meta.env.DEV ? `${base}__alta_pages/` : base;
  progress("Preparing source and GitHub Pages files…");
  const inventory = await (await fetchFile(`${pagesBase}alta-export.json`)).json();
  const zip = new JSZip();
  const configText = JSON.stringify(config, null, 2) + "\n";
  zip.file("scene-config.json", configText);
  zip.file("source/public/scene-config.json", configText);
  zip.file(".nojekyll", "");
  zip.file("EXPORT-README.txt", [
    "ALTA • AI Study Room",
    "GitHub Pages: upload the extracted contents to the published branch or directory.",
    "Offline preview: serve the extracted directory with a local static server; do not double-click index.html.",
    "Edit: open source/, install dependencies with npm ci and use npm run dev. npm run build creates a fresh dist/.",
    "The AI tutor still needs internet and Puter. The room, models and sounds are included.",
  ].join("\n"));
  for (const [path, source] of Object.entries(inventory.sources)) zip.file(`source/${path}`, source);

  const files = new Map();
  function queue(url, file) {
    if (!files.has(url)) files.set(url, []);
    files.get(url).push(file);
  }
  for (const file of inventory.files) {
    queue(`${pagesBase}${file}`, file);
    if (file.startsWith("alta-draco/")) queue(`${pagesBase}${file}`, `source/public/${file}`);
  }
  for (const [path, url] of Object.entries(models)) queue(url, `source/design/ATLA/assets/${path.split("/").pop()}`);
  for (const [name, url] of Object.entries(sounds)) queue(url, `source/design/ATLA/sounds/${name}`);

  const queueEntries = [...files];
  let done = 0;
  await Promise.all(Array.from({ length: 8 }, async () => {
    for (let job = queueEntries.shift(); job; job = queueEntries.shift()) {
      const [url, paths] = job;
      const data = await (await fetchFile(url)).arrayBuffer();
      for (const path of paths) zip.file(path, data);
      progress(`Gathering files: ${++done} / ${files.size}`);
    }
  }));
  const blob = await zip.generateAsync({ type: "blob", compression: "STORE" }, ({ percent }) => {
    progress(`Packing ZIP: ${Math.round(percent)}%`);
  });
  downloadFile("ALTA-full-project.zip", blob);
}

