import * as THREE from "three";

// ALTA's framed artwork shares these authored mesh names; calendars use the same
// frame but keep their existing interactive calendar behavior.
export function isPoster(assetName, root) {
  if (assetName === "2026" || assetName === "2027") return false;
  let framed = false;
  root.traverse(child => { if (child.isMesh && /^cuadro2_marco/i.test(child.name)) framed = true; });
  return framed;
}

export function posterView(root, roomPoint, camera, blockers = []) {
  const box = new THREE.Box3().setFromObject(root);
  const center = box.getCenter(new THREE.Vector3());
  const size = box.getSize(new THREE.Vector3());
  // The shortest horizontal bounding-box axis is the normal of the wall-mounted frame.
  const normal = size.x < size.z ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 0, 1);
  if (normal.dot(new THREE.Vector3().subVectors(roomPoint, center)) < 0) normal.negate();
  const width = size.x < size.z ? size.z : size.x;
  const vFov = THREE.MathUtils.degToRad(camera.getEffectiveFOV());
  const hFov = 2 * Math.atan(Math.tan(vFov / 2) * camera.aspect);
  const distance = Math.max(size.y / (2 * Math.tan(vFov / 2)), width / (2 * Math.tan(hFov / 2))) * 1.3;
  const ray = new THREE.Raycaster(center.clone().addScaledVector(normal, 0.04), normal, 0, distance);
  const obstruction = ray.intersectObjects(blockers, true)[0];
  // Keep the eye in front of the closest obstruction, rather than inside it.
  const safeDistance = obstruction ? Math.max(0.1, Math.min(distance, obstruction.distance - 0.12)) : distance;
  return { target: center, position: center.clone().addScaledVector(normal, safeDistance), normal };
}

