export const VIEWS = Object.freeze({ desk: "Desk", shelf: "Shelf", cat: "Cat", door: "Door", full: "Full Room" });
export const DEFAULT_CAMERA_PRESETS = Object.freeze({
  desk: { position: [0.23310600019264838, 4.546275453292245, 0.5008599384544673], target: [0.4434646618151426, 4.085799264009773, -0.5474067253168983] },
  shelf: { position: [0.8523110050436006, 4.864825207875022, 0.4186871986406072], target: [-0.48211883237435627, 4.04330341457361, 0.008011884096796705] },
  cat: { position: [0.24015443608040044, 4.846748295639943, 0.17533547452469922], target: [1.2455866233209192, 3.0779849306068483, 0.6265302481114267] },
  door: { position: [3.4350895236291743, 4.733567942809824, 0.6398780138117275], target: [2.5943456004757617, 4.298979649457343, 0.44893919857734077] },
  full: { position: [-0.6397498801246867, 5.47456972023518, 1.7327000336518696], target: [0.3984283890535, 4.25092999699529, 0.6718811322494729] },
});
export const LIGHTS = Object.freeze({
  toneMappingExposure: { label: "Exposure", max: 5, step: 0.01, fallback: 1.35 },
  ambientIntensity: { label: "Ambient light", max: 10, step: 0.01, fallback: 1.4 },
  ceilingIntensity: { label: "Ceiling point light", max: 100, step: 0.1, fallback: 18 },
});

function vector(value) {
  return Array.isArray(value) && value.length === 3 && value.every(Number.isFinite);
}

export function mergeSceneConfig(...sources) {
  const config = { version: 1, cameraPresets: {}, lighting: {} };
  for (const key of Object.keys(LIGHTS)) config.lighting[key] = LIGHTS[key].fallback;
  for (const source of [{ cameraPresets: DEFAULT_CAMERA_PRESETS }, ...sources]) {
    for (const key of Object.keys(VIEWS)) {
      const preset = source?.cameraPresets?.[key];
      if (vector(preset?.position) && vector(preset?.target) && preset.position.some((n, i) => n !== preset.target[i])) {
        config.cameraPresets[key] = { position: [...preset.position], target: [...preset.target] };
      }
    }
    for (const [key, { max }] of Object.entries(LIGHTS)) {
      const value = source?.lighting?.[key];
      if (Number.isFinite(value) && value >= 0 && value <= max) config.lighting[key] = value;
    }
  }
  return config;
}

export async function loadSceneConfig(url) {
  try {
    const response = await fetch(url, { signal: AbortSignal.timeout(2500) });
    // Vite may serve the HTML fallback when the optional file is absent.
    if (!response.ok || response.headers.get("content-type")?.includes("text/html")) return undefined;
    const config = await response.json();
    console.info("[ALTA] Loaded scene-config.json");
    return config;
  } catch (error) {
    console.warn("[ALTA] Optional scene config could not be loaded", error);
    return undefined;
  }
}

