const MAX_TEXT = 120_000;
const MAX_SHELF = 1_000_000;
const MAX_IMAGE = 2_500_000;
const IMAGE_TYPES = { png: 1, jpg: 1, jpeg: 1, webp: 1 };
const TEXT_TYPES = { txt: 1, md: 1, markdown: 1, csv: 1, json: 1, log: 1, pdf: 1 };

export async function readImageFile(file) {
  if (!IMAGE_TYPES[file.name.split('.').pop().toLowerCase()]) throw new Error('Choose a PNG, JPG or WebP image.');
  if (file.size > 8 * 1024 * 1024) throw new Error('Choose an image under 8 MB.');
  const dataUrl = await new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(new Error('Could not read that image.'));
    reader.readAsDataURL(file);
  });
  return dataUrl.length > MAX_IMAGE ? dataUrl.slice(0, 0) || (await downscale(dataUrl)) : dataUrl;
}

async function downscale(dataUrl) {
  const image = await new Promise((resolve, reject) => {
    const el = new Image();
    el.onload = () => resolve(el);
    el.onerror = () => reject(new Error('That image could not be decoded.'));
    el.src = dataUrl;
  });
  const scale = Math.min(1280 / image.naturalWidth, 1280 / image.naturalHeight, 1);
  const canvas = document.createElement('canvas');
  canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
  canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
  canvas.getContext('2d').drawImage(image, 0, 0, canvas.width, canvas.height);
  return canvas.toDataURL('image/webp', 0.82);
}

export async function readStudyFile(file) {
  const extension = file.name.split('.').pop().toLowerCase();
  if (!['txt', 'md', 'pdf'].includes(extension)) throw new Error('Choose a TXT, Markdown, or PDF file.');
  if (file.size > 15 * 1024 * 1024) throw new Error('Choose a file under 15 MB.');
  if (extension !== 'pdf') return (await file.text()).slice(0, MAX_TEXT).trim();
  const [{ getDocument, GlobalWorkerOptions }, { default: workerUrl }] = await Promise.all([
    import('pdfjs-dist'), import('pdfjs-dist/build/pdf.worker.min.mjs?url'),
  ]);
  GlobalWorkerOptions.workerSrc = workerUrl;
  const task = getDocument({ data: await file.arrayBuffer(), isEvalSupported: false });
  try {
    const pdf = await task.promise;
    let text = '';
    for (let page = 1; page <= pdf.numPages && text.length < MAX_TEXT; page++) {
      const content = await (await pdf.getPage(page)).getTextContent();
      text += content.items.filter(item => 'str' in item).map(item => item.str + (item.hasEOL ? '\n' : ' ')).join('') + '\n\n';
    }
    return text.slice(0, MAX_TEXT).trim();
  } finally {
    await task.destroy();
  }
}

const words = text => text.match(/\p{L}[\p{L}\p{M}’-]{3,}/gu) || [];
const ignored = new Set('about after also another because before being between could during every first from have into more most other over same should some such than that their them then there these they this those through using very were what when where which while will with would your'.split(' '));
const key = word => word.trim().normalize('NFKC').toLowerCase();
const shuffle = list => {
  for (let i = list.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [list[i], list[j]] = [list[j], list[i]];
  }
  return list;
};

export function makeQuestions(text) {
  const sentences = [...new Set(text.replace(/```[\s\S]*?```/g, ' ').split(/(?<=[.!?])\s+|\n+/u).map(line => line.trim()))];
  const terms = [...new Map(words(text).filter(word => !ignored.has(key(word))).map(word => [key(word), word])).values()].slice(0, 600);
  const questions = [];
  for (const line of shuffle(sentences.filter(line => line.length >= 16 && line.length <= 380))) {
    const candidates = [...line.matchAll(/\p{L}[\p{L}\p{M}’-]{3,}/gu)].filter(match => !ignored.has(key(match[0])));
    if (!candidates.length) continue;
    const match = candidates[Math.floor(Math.random() * candidates.length)];
    const answer = match[0];
    const lookupLine = key(line);
    const distractors = shuffle(terms.filter(word => !lookupLine.includes(key(word)))).slice(0, 3);
    questions.push({ prompt: line.slice(0, match.index) + '_____' + line.slice(match.index + answer.length), answer,
      choices: distractors.length >= 2 ? shuffle([answer, ...distractors]) : [] });
    if (questions.length === 12) break;
  }
  return questions;
}

export function nextAlarmTime(time, now = new Date()) {
  if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)) return NaN;
  const [hours, minutes] = time.split(':').map(Number);
  const at = new Date(now);
  at.setHours(hours, minutes, 0, 0);
  if (at <= now) at.setDate(at.getDate() + 1);
  return +at;
}

export function nextAlarmAt(dateKey, time, now = Date.now()) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateKey) || !/^([01]\d|2[0-3]):[0-5]\d$/.test(time || '')) return NaN;
  const at = nextAlarmAt.last(dateKey, time);
  return Number.isFinite(at) && at + 60_000 > now ? at : NaN;
}

nextAlarmAt.last = (dateKey, time) => {
  const [hours, minutes] = time.split(':').map(Number);
  const [year, month, day] = dateKey.split('-').map(Number);
  return +new Date(year, month - 1, day, hours, minutes, 0, 0);
};

export function createStudyTools({ storage, content, data, openPanel, renderIfOpen, escapeHTML: esc, showToast, chime }) {
  let documents = storage.load('documents', []);
  let activeId = storage.load('active-document', '');
  let alarms = storage.load('alarms', []);
  let tasks = storage.load('calendar-tasks', []);
  let diary = storage.load('diary', []);
  let monthCursor = new Date();
const dateKeyOf = date => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
let selectedDay = dateKeyOf(new Date());
  let ringing = null;
  let uploading = false;
  let quiz = null;
  let timer = null;
  let sketch = { color: '#1b1b1f', drawing: false, erased: false };
  const notice = document.getElementById('alarmNotice');
  const message = document.getElementById('alarmMessage');
  const dismiss = document.getElementById('dismissAlarm');
  const enable = document.getElementById('playAlarm');
  const button = (action, label, extra = '') => `<button type="button" class="secondary-btn" data-action="${action}" ${extra}>${label}</button>`;
  const active = () => documents.find(doc => doc.id === activeId);
  const save = (name, value) => {
    try { storage.save(name, value); return true; }
    catch (error) { console.warn('[ALTA] Could not save', name, error); showToast('Could not save. Check your browser storage.'); return false; }
  };
  const dateLabel = at => new Date(at).toLocaleString(undefined, { weekday: 'short', hour: 'numeric', minute: '2-digit' });
  const timerLabel = seconds => `${Math.floor(seconds / 60)}:${String(Math.max(0, seconds % 60)).padStart(2, '0')}`;

  function soundAlarm() {
    const alarm = ringing;
    if (!alarm) return;
    chime.play().then(() => { if (ringing === alarm) enable.hidden = true; }).catch(error => {
      if (ringing !== alarm) return;
      enable.hidden = false;
      message.textContent = `${alarm.label} — tap to play the chime.`;
      console.info('[ALTA] Alarm audio needs a browser gesture', error.name);
    });
  }
  enable.addEventListener('click', soundAlarm);
  dismiss.addEventListener('click', () => {
    if (!ringing) return;
    const remaining = alarms.filter(alarm => alarm.id !== ringing.id);
    save('alarms', remaining);
    alarms = remaining;
    ringing = null;
    chime.pause();
    chime.currentTime = 0;
    notice.hidden = true;
    checkAlarms();
    renderIfOpen('alarms');
  });
  function checkAlarms() {
    if (ringing) return;
    ringing = alarms.filter(alarm => alarm.at <= Date.now()).sort((a, b) => a.at - b.at)[0] || null;
    if (!ringing) return;
    message.textContent = ringing.label;
    notice.hidden = false;
    enable.hidden = true;
    console.info('[ALTA] Study alarm triggered');
    soundAlarm();
    renderIfOpen('alarms');
  }
  window.setInterval(checkAlarms, 1000);
  document.addEventListener('visibilitychange', checkAlarms);

  const tickTimer = () => {
    if (!timer?.running) return;
    timer.remaining = getSecondsLeft(timer.endAt);
    if (timer.remaining <= 0) {
      timer.running = false;
      timer.remaining = 0;
      console.info('[ALTA] Study timer finished');
      soundChime();
      showToast('Study timer complete');
    }
    renderIfOpen('timer');
  };
  window.setInterval(tickTimer, 500);

  function soundChime() {
    chime.currentTime = 0;
    chime.play().catch(() => {});
  }

  const sources = () => ({
    document: active()?.text || '',
    notebook: data.notebook.text || '',
    tutor: data.tutor.history.filter(item => item.role === 'assistant' || item.role === 'user').slice(-8).map(item => item.content).join('\n'),
  });
  function startQuiz(source, mode) {
    const questions = makeQuestions(sources()[source] || '').filter(question => mode !== 'choice' || question.choices.length);
    quiz = { source, mode, questions, index: 0, answered: 0, correct: 0, result: null, finished: false };
    console.info(`[ALTA] Play Mode: ${questions.length} questions from ${source}`);
    openPanel('play');
  }
  function grade(answer) {
    const question = quiz?.questions[quiz.index];
    if (!question || quiz.result || quiz.finished || !answer?.trim()) return;
    const correct = key(answer) === key(question.answer);
    quiz.answered++;
    quiz.correct += Number(correct);
    quiz.result = { correct };
    renderIfOpen('play');
    content.querySelector('[data-action="quiz-next"]')?.focus();
  }

  const getSecondsLeft = endAt => Math.max(0, Math.round((endAt - Date.now()) / 1000));
  function setTimerPreset(minutes) {
    if (!Number.isFinite(minutes) || minutes <= 0 || minutes > 240) return;
    timer = { running: false, minutes, remaining: Math.round(minutes * 60), endAt: null };
    renderIfOpen('timer');
  }
  function toggleTimer() {
    if (!timer) setTimerPreset(25);
    if (!timer) return;
    if (timer.running) {
      timer.running = false;
      timer.remaining = getSecondsLeft(timer.endAt);
      timer.endAt = null;
    } else if (timer.remaining > 0) {
      timer.running = true;
      timer.endAt = Date.now() + timer.remaining * 1000;
    }
    renderIfOpen('timer');
  }
  function resetTimer() {
    if (!timer) return;
    timer.running = false;
    timer.endAt = null;
    timer.remaining = Math.round(timer.minutes * 60);
    renderIfOpen('timer');
  }
  function render(panel) {
    if (panel === 'timer') {
      const running = timer?.running;
      content.innerHTML = `<section class="module-card study-form">
        <div class="timer-display-lg mono">${timerLabel(timer?.running ? getSecondsLeft(timer.endAt) : (timer?.remaining ?? 0))}</div>
        <div class="row wrap">${[15, 25, 45].map(minutes => button('timer-preset', `${minutes}m`, `data-minutes="${minutes}" ${timer?.minutes === minutes ? 'aria-pressed="true"' : ''}`)).join('')}
        <label>Custom<input type="number" min="1" max="240" data-bind="timer-custom" value="${timer?.minutes && ![15, 25, 45].includes(timer.minutes) ? timer.minutes : ''}" placeholder="min"></label></div>
        <div class="row wrap">${button('timer-toggle', running ? 'Pause' : timer?.remaining ? 'Start' : 'Start', `aria-pressed="${Boolean(running)}"`)}` +
        `${button('timer-reset', 'Reset')}</div>
        <p>${running ? 'Focus! A gentle chime plays when the timer finishes.' : 'Tap a preset, then Start.'}</p></section>`;
    } else if (panel === 'alarms') {
      const year = monthCursor.getFullYear();
      const month = monthCursor.getMonth();
      const first = new Date(year, month, 1);
      const days = new Date(year, month + 1, 0).getDate();
      const lead = first.getDay();
      const todayKey = dateKeyOf(new Date());
      let grid = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(day => `<span class="study-dow">${day.slice(0,3)}</span>`).join('');
      for (let i = 0; i < lead; i++) grid += '<button type="button" class="study-day" aria-hidden="true" disabled></button>';
      for (let day = 1; day <= days; day++) {
        const dateKey = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
        const hasItems = tasks.some(task => task.date === dateKey) || alarms.some(alarm => alarm.date === dateKey);
        grid += `<button type="button" class="study-day" data-action="calendar-day" data-date="${dateKey}" data-date-label="${new Date(year, month, day).toDateString()}" aria-pressed="${selectedDay === dateKey}" ${dateKey === todayKey ? 'data-today' : ''}>${day}${hasItems ? '<span class="study-day-dot"></span>' : ''}</button>`;
      }
      const dayItems = [
        ...tasks.filter(task => task.date === selectedDay).map(task => ({ ...task, kind: 'task' })),
        ...alarms.filter(alarm => alarm.date === selectedDay).map(alarm => ({ ...alarm, kind: 'alarm' })),
      ];
      content.innerHTML = `<section class="module-card study-month">
        <div class="study-month-head">${button('calendar-prev', '‹')}<h3>${monthCursor.toLocaleString(undefined, { month: 'long', year: 'numeric' })}</h3>${button('calendar-next', '›')}</div>
        <div class="study-month-grid">${grid}</div>
        <p class="guide-hint">Tap a date to add study tasks, exams or timed alarms.</p></section>
        <section class="module-card study-form"><h3>${selectedDay ? new Date(selectedDay + 'T00:00').toDateString() : 'Pick a date'}</h3>
          ${selectedDay ? `<form id="studyDayForm" class="study-form">
            <label>Task or exam title<input name="label" type="text" maxlength="100" required placeholder="Midterm review"></label>
            <label>Timed alarm (optional)<input name="time" type="time"></label>
            <button class="primary-btn">Add to this day</button></form>` : '<p>Choose a date on the calendar.</p>'}
          <div class="study-tasks">${dayItems.map(item => `<div class="study-task"><div><strong>${esc(item.label)}</strong>${item.kind === 'alarm' ? `<p>⏰ ${esc(dateLabel(item.at))}</p>` : ''}</div>
          ${button(item.kind === 'alarm' ? 'alarm-remove' : 'task-remove', 'Remove', `data-id="${esc(item.id)}"`)}</div>`).join('') || '<p class="guide-hint">Nothing scheduled here yet.</p>'}</div></section>
        ${alarms.some(alarm => !alarm.date) ? `<section class="module-card"><h3>Other timed reminders</h3>${alarms.filter(alarm => !alarm.date).map(alarm =>
          `<div class="study-list-item"><div><strong>${esc(alarm.label)}</strong><p>${alarm.id === ringing?.id ? 'Ringing' : esc(dateLabel(alarm.at))}</p></div>
          ${alarm.id !== ringing?.id ? button('alarm-remove', 'Dismiss', `data-id="${esc(alarm.id)}"`) : ''}</div>`).join('')}</section>` : ''}`;
    } else if (panel === 'documents') {
      const preview = item => item.image ? `<img src="${item.image}" alt="${esc(item.name)}" class="study-thumb">` : `<span class="pill">${(item.kind || 'file').toUpperCase()}</span>`;
      content.innerHTML = `<section class="module-card study-form"><h3>Add study material</h3>
        <label>Upload files, images or PDFs<input type="file" accept=".txt,.md,.markdown,.pdf,.png,.jpg,.jpeg,.webp" data-bind="document-upload" ${uploading ? 'disabled' : ''}></label>
        <p>${uploading ? 'Reading your file…' : 'TXT, Markdown, PDF and images are saved on this device. Scanned PDFs without selectable text are kept as file references.'}</p>
        <form id="studyLinkForm" class="study-form"><label>Google Drive, Docs or web link<input name="url" type="url" required placeholder="https://drive.google.com/…"></label>
        <label>Title<input name="label" type="text" maxlength="100" placeholder="Biology notes"></label><button class="primary-btn">Add Link</button></form></section>
        <section class="module-card"><h3>Your shelf</h3>${documents.map(doc => `<div class="study-list-item"><div>${preview(doc)}<div><strong>${esc(doc.name)}</strong><p>${active()?.id === doc.id ? 'Active in the book' : doc.kind === 'link' ? 'Saved link' : 'On the shelf'}${doc.text ? '' : ' · file reference only'}</p></div></div>
        <div class="row wrap">${button('document-active', 'Make active', `data-id="${esc(doc.id)}" ${active()?.id === doc.id ? 'disabled' : ''}`)}${button('document-read', 'Open in Diary', `data-id="${esc(doc.id)}"`)}${button('document-remove', 'Remove', `data-id="${esc(doc.id)}"`)}</div></div>`).join('') || '<p>The shelf is empty.</p>'}
        <p class="guide-hint">Diary notes and sketches saved this session appear on the book page.</p></section>`;
    } else if (panel === 'reader') {
      const doc = active();
      content.innerHTML = `<section class="module-card study-form"><h3>${esc(doc?.name || 'No active document')}</h3>
        ${doc?.image ? `<img src="${doc.image}" alt="${esc(doc.name)}" class="study-thumb">` : ''}
        ${doc?.url ? `<p><a href="${esc(doc.url)}" target="_blank" rel="noopener">${esc(doc.url)}</a></p>` : ''}
        ${doc?.image ? `<img src="${doc.image}" class="reader-image" alt="${esc(doc.name)}">` : ''}
        ${doc?.text ? `<div class="study-document">${esc(doc.text)}</div>` : ''}
        ${doc?.url ? '' : ''}
        ${!doc?.image && !doc?.text ? `<p>${doc ? 'This file has no readable text. Add notes or a sketch below, or pick another document.' : 'Choose study material on the shelf.'}</p>` : ''}
        <div class="row wrap">${button('document-shelf', 'Document Shelf')}${doc?.text ? button('document-quiz', 'Quiz this document') : ''}</div>
        <label>Quick notes · Study Notebook<textarea rows="4" data-bind="notebook-text">${esc(data.notebook.text)}</textarea></label>
        <h3>Session diary</h3>
        ${diary.length ? `<div class="study-tasks">${diary.slice(0, 40).map(entry => `<div class="study-task"><div><strong>${esc(entry.kind)}</strong><p>${entry.kind === 'sketch' ? '<span class="pill">sketch saved</span>' : esc(entry.text)}</p></div>${button('diary-remove', 'Remove', `data-id="${esc(entry.id)}"`)}</div>`).join('')}</div>` : '<p class="guide-hint">Notes, pasted highlights and sketches you save appear here for this session.</p>'}
        <div class="row wrap">${button('diary-save-session', 'Save Session to Shelf')}</div></section>`;
    } else if (panel === 'play') {
      const available = sources();
      const question = quiz?.questions[quiz.index];
      content.innerHTML = `<section class="module-card"><form id="studyQuizForm" class="study-form"><h3>Build a quick quiz</h3>
        <label>Study material <select name="source">${[['document','Active shelf document'],['notebook','Study Notebook'],['tutor','Recent AI Tutor topics']].map(([id,label]) => `<option value="${id}" ${!available[id].trim() ? 'disabled' : ''} ${quiz?.source === id && available[id].trim() ? 'selected' : ''}>${label}</option>`).join('')}</select></label>
        <label>Mode <select name="mode"><option value="mix">Mixed</option><option value="choice" ${quiz?.mode === 'choice' ? 'selected' : ''}>Multiple choice</option><option value="rapid" ${quiz?.mode === 'rapid' ? 'selected' : ''}>Rapid-fire typing</option></select></label>
        <button class="primary-btn" ${Object.values(available).some(text => text.trim()) ? '' : 'disabled'}>Start Quiz</button>
        ${Object.values(available).some(text => text.trim()) ? '' : '<p>Add notebook notes, choose a shelf document, or ask the tutor a question first.</p>'}</form></section>
        ${quiz ? `<section class="module-card study-form"><p role="status">Score: ${quiz.correct} / ${quiz.answered}${quiz.finished ? ' · Quiz complete' : ''}</p>
        ${!question ? '<p>Not enough usable text for this mode. Add more study material or try Mixed.</p>' : quiz.finished ? '<p>Start a new quiz to practice again.</p>' : `<h3>Question ${quiz.index + 1} of ${quiz.questions.length}</h3><p>${esc(question.prompt)}</p>
        ${quiz.result ? `<p role="status">${quiz.result.correct ? 'Correct!' : 'Not quite.'} Answer: <strong>${esc(question.answer)}</strong></p>${button('quiz-next', quiz.index + 1 === quiz.questions.length ? 'Finish Quiz' : 'Next Question')}` :
        question.choices.length && (quiz.mode === 'choice' || (quiz.mode === 'mix' && quiz.index % 2 === 0)) ? `<div class="row wrap">${question.choices.map((choice, index) => button('quiz-choice', esc(choice), `data-index="${index}"`)).join('')}</div>` :
        '<form id="studyAnswerForm" class="study-form"><label>Fill in the blank<input name="answer" type="text" required autocomplete="off" maxlength="120"></label><button class="primary-btn">Check Answer</button></form>'}`}</section>` : ''}`;
    } else if (panel === 'notes') {
      content.innerHTML = `<section class="module-card study-form"><h3>Sketch pad</h3>
        <canvas class="study-sketch" data-bind="sketch-canvas" width="960" height="720" aria-label="Freehand sketch pad"></canvas>
        <div class="study-swatches"><label>Pen <input type="color" data-bind="sketch-color" value="${esc(sketch.color)}"></label>
        ${button('sketch-eraser', 'Eraser', `aria-pressed="${sketch.erased}"`)}${button('sketch-clear', 'Clear')}</div>
        <div class="row wrap">${button('sketch-save-diary', 'Save to Diary')}${button('sketch-save-shelf', 'Save to Shelf')}</div>
        <p class="guide-hint">Draw with the mouse or a finger.</p></section>
        <section class="module-card study-form"><h3>Quick notes</h3>
        <label>Type or paste formulas and notes<textarea rows="6" data-bind="sketch-note">${esc(sketch.note || '')}</textarea></label>
        <div class="row wrap">${button('sketch-copy', 'Copy Notes')}${button('sketch-note-diary', 'Save to Diary')}${button('sketch-note-shelf', 'Save to Shelf')}</div>
        <p class="guide-hint">Copy puts your notes on the clipboard.</p></section>`;
    } else return false;
    if (panel === 'notes') requestAnimationFrame(() => attachSketch());
    return true;
  }
  content.addEventListener('submit', event => {
    const form = event.target;
    if (!['studyAlarmForm','studyQuizForm','studyAnswerForm','studyLinkForm','studyDayForm'].includes(form.id)) return;
    event.preventDefault();
    const fields = new FormData(form);
    if (form.id === 'studyQuizForm') startQuiz(fields.get('source'), fields.get('mode'));
    else if (form.id === 'studyAnswerForm') grade(fields.get('answer'));
    else if (form.id === 'studyLinkForm') {
      const url = String(fields.get('url') || '').trim();
      if (!/^https?:\/\//i.test(url)) return;
      const label = String(fields.get('label') || '').trim() || new URL(url).hostname;
      const doc = { id: crypto.randomUUID(), name: label, kind: 'link', url, text: '' };
      const next = [...documents, doc];
      if (JSON.stringify(next).length > MAX_SHELF) { showToast('The shelf is full. Remove an older item first.'); return; }
      if (save('documents', next)) { documents = next; if (!active() && save('active-document', doc.id)) activeId = doc.id; renderIfOpen('documents'); console.info('[ALTA] Shelf link added'); }
    } else if (form.id === 'studyDayForm') {
      const label = String(fields.get('label') || '').trim();
      const time = String(fields.get('time') || '').trim();
      const at = time ? nextAlarmAt(selectedDay, time) : NaN;
      if (label && Number.isFinite(at)) {
        const next = [...alarms, { id: crypto.randomUUID(), at, date: selectedDay, label }];
        if (save('alarms', next)) { alarms = next; console.info('[ALTA] Study alarm scheduled'); }
      } else if (label) {
        const next = [...tasks, { id: crypto.randomUUID(), date: selectedDay, label }];
        if (save('calendar-tasks', next)) { tasks = next; console.info('[ALTA] Study task added'); }
      }
      renderIfOpen('alarms');
    }
  });
  function click(el) {
    const { action, id, index } = el.dataset;
    switch (action) {
      case 'calendar-day': selectedDay = el.dataset.date; renderIfOpen('alarms'); return true;
      case 'calendar-prev': monthCursor = new Date(monthCursor.getFullYear(), monthCursor.getMonth() - 1, 1); renderIfOpen('alarms'); return true;
      case 'calendar-next': monthCursor = new Date(monthCursor.getFullYear(), monthCursor.getMonth() + 1, 1); renderIfOpen('alarms'); return true;
      case 'task-remove': {
        const next = tasks.filter(task => task.id !== id);
        if (save('calendar-tasks', next)) { tasks = next; renderIfOpen('alarms'); }
        return true;
      }
      case 'timer-preset': setTimerPreset(Number(el.dataset.minutes)); return true;
      case 'timer-toggle': toggleTimer(); return true;
      case 'timer-reset': resetTimer(); return true;
      case 'sketch-eraser': sketch.erased = !sketch.erased; renderIfOpen('notes'); return true;
      case 'sketch-clear': clearSketch(); renderIfOpen('notes'); return true;
      case 'sketch-copy': copyNotes(); return true;
      case 'sketch-save-diary': saveDiary('sketch'); return true;
      case 'sketch-save-shelf': saveToShelf('sketch'); return true;
      case 'sketch-note-diary': saveDiary('note'); return true;
      case 'sketch-note-shelf': saveToShelf('note'); return true;
      case 'diary-save-session': saveSession(); return true;
      case 'diary-remove': {
        const next = diary.filter(entry => entry.id !== id);
        if (save('diary', next)) { diary = next; renderIfOpen('reader'); }
        return true;
      }
      case 'alarm-remove': {
        const next = alarms.filter(alarm => alarm.id !== id);
        if (save('alarms', next)) { alarms = next; renderIfOpen('alarms'); }
        return true;
      }
      case 'document-active': if (save('active-document', id)) { activeId = id; renderIfOpen('documents'); } return true;
      case 'document-remove': {
        const next = documents.filter(doc => doc.id !== id);
        if (save('documents', next)) {
          documents = next;
          if (activeId === id) { activeId = next[0]?.id || ''; save('active-document', activeId); }
          renderIfOpen('documents');
        }
        return true;
      }
      case 'document-shelf': openPanel('documents'); return true;
      case 'document-read': if (save('active-document', id)) { activeId = id; } openPanel('reader'); return true;
      case 'document-quiz': startQuiz('document', 'mix'); return true;
      case 'quiz-choice': grade(quiz?.questions[quiz.index]?.choices[Number(index)]); return true;
      case 'quiz-next':
        if (quiz?.result && !quiz.finished) {
          if (quiz.index + 1 === quiz.questions.length) quiz.finished = true;
          else { quiz.index++; quiz.result = null; }
          renderIfOpen('play');
          content.querySelector('[name="answer"], [data-action="quiz-choice"]')?.focus();
        }
        return true;
      default: return false;
    }
  }
  async function upload(file) {
    if (!file || uploading) return;
    uploading = true;
    renderIfOpen('documents');
    try {
      const extension = file.name.split('.').pop().toLowerCase();
      let text = '';
      let image = '';
      if (IMAGE_TYPES[extension]) {
        const dataUrl = await readImageFile(file);
        if (!dataUrl) throw new Error('That image is too large for the shelf.');
        image = dataUrl;
      } else if (TEXT_TYPES[extension]) {
        text = await readStudyFile(file);
        if (!text && extension !== 'pdf') throw new Error('This document has no readable text.');
      } else {
        throw new Error('Choose a TXT, Markdown, PDF or image file.');
      }
      const doc = { id: crypto.randomUUID(), name: file.name, kind: extension === 'pdf' ? 'pdf' : image ? 'image' : 'text', text, image };
      const next = [...documents, doc];
      if (JSON.stringify(next).length > MAX_SHELF) throw new Error('The shelf is full. Remove an older document first.');
      if (save('documents', next)) {
        documents = next;
        if (!active() && save('active-document', doc.id)) activeId = doc.id;
        showToast(image ? 'Image added to the shelf' : text ? 'Document added to the shelf' : 'PDF reference saved; no selectable text found');
        console.info('[ALTA] Shelf document imported', { hasText: Boolean(text) });
      }
    } catch (error) {
      console.warn('[ALTA] Document import failed', error.name);
      showToast(error.message || 'Unable to read that document.');
    } finally { uploading = false; renderIfOpen('documents'); }
  }

  function attachSketch() {
    const canvas = content.querySelector('.study-sketch');
    if (!canvas || canvas.attached) return;
    canvas.attached = true;
    const ctx = canvas.getContext('2d');
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    const point = event => {
      const rect = canvas.getBoundingClientRect();
      return [ (event.clientX - rect.left) * canvas.width / rect.width, (event.clientY - rect.top) * canvas.height / rect.height ];
    };
    const start = event => {
      if (event.pointerType === 'mouse' && event.button !== 0) return;
      event.preventDefault();
      canvas.setPointerCapture(event.pointerId);
      canvas.stroke = [point(event)];
    };
    const move = event => {
      if (!canvas.stroke) return;
      event.preventDefault();
      canvas.stroke.push(point(event));
      ctx.strokeStyle = sketch.erased ? '#ffffff' : sketch.color;
      ctx.lineWidth = sketch.erased ? 26 : 3;
      const [x, y] = canvas.stroke.at(-1);
      const [px, py] = canvas.stroke.at(-2);
      ctx.beginPath();
      ctx.moveTo(px, py);
      ctx.lineTo(x, y);
      ctx.stroke();
    };
    const end = event => { canvas.stroke = null; };
    canvas.addEventListener('pointerdown', start);
    canvas.addEventListener('pointermove', move);
    canvas.addEventListener('pointerup', end);
    canvas.addEventListener('pointercancel', end);
    canvas.addEventListener('pointerleave', end);
  }
  function clearSketch() {
    const canvas = content.querySelector('.study-sketch');
    if (canvas) canvas.getContext('2d').clearRect(0, 0, canvas.width, canvas.height);
  }
  async function copyNotes() {
    const text = sketch.note || '';
    if (!text.trim()) { showToast('Nothing to copy yet.'); return; }
    try {
      await navigator.clipboard.writeText(text);
      showToast('Notes copied');
    } catch {
      showToast('Copy is blocked here. Select the text instead.');
    }
  }
  const addDiary = (kind, payload) => {
    const entry = { id: crypto.randomUUID(), kind, ...payload, at: Date.now() };
    diary = [entry, ...diary].slice(0, 80);
    save('diary', diary);
    renderIfOpen('reader');
  };
  function saveDiary(kind) {
    if (kind === 'sketch') {
      const canvas = content.querySelector('.study-sketch');
      if (!canvas || !canvas.toDataURL) return;
      const image = canvas.toDataURL('image/webp', 0.8);
      if (image.length > MAX_IMAGE) { showToast('That sketch is too large to save.'); return; }
      addDiary('sketch', { image });
    } else {
      const text = String(sketch.note || '').trim();
      if (!text) { showToast('Nothing to save yet.'); return; }
      addDiary('note', { text });
    }
    showToast('Saved to the session diary');
  }
  function saveToShelf(kind) {
    if (kind === 'sketch') {
      const canvas = content.querySelector('.study-sketch');
      if (!canvas || !canvas.toDataURL) return;
      const image = canvas.toDataURL('image/webp', 0.8);
      if (image.length > MAX_IMAGE) { showToast('That sketch is too large to save.'); return; }
      const doc = { id: crypto.randomUUID(), name: `Sketch ${new Date().toLocaleString()}`, kind: 'image', image, text: '' };
      const next = [...documents, doc];
      if (JSON.stringify(next).length > MAX_SHELF) { showToast('The shelf is full. Remove an older item first.'); return; }
      if (save('documents', next)) { documents = next; console.info('[ALTA] Sketch archived to shelf'); }
    } else {
      const text = String(sketch.note || '').trim();
      if (!text) { showToast('Nothing to save yet.'); return; }
      const doc = { id: crypto.randomUUID(), name: `Notes ${new Date().toLocaleString()}`, kind: 'text', text, image: '' };
      const next = [...documents, doc];
      if (JSON.stringify(next).length > MAX_SHELF) { showToast('The shelf is full. Remove an older item first.'); return; }
      if (save('documents', next)) { documents = next; console.info('[ALTA] Notes archived to shelf'); }
    }
    showToast('Archived to the shelf');
  }
  function saveSession() {
    const text = diary.map(entry => entry.kind === 'sketch' ? '[sketch]' : entry.text).filter(Boolean).join('\n');
    const doc = { id: crypto.randomUUID(), name: `Diary ${new Date().toLocaleDateString()}`, kind: 'text', text, image: '' };
    const next = [...documents, doc];
    if (!text.trim()) { showToast('The diary is empty.'); return; }
    if (JSON.stringify(next).length > MAX_SHELF) { showToast('The shelf is full. Remove an older item first.'); return; }
    if (save('documents', next)) { documents = next; showToast('Session saved to the shelf'); }
  }
  return { render, click, change(field) {
    const bind = field.dataset.bind;
    if (bind === 'document-upload') { upload(field.files?.[0]); return true; }
    if (bind === 'timer-custom') { setTimerPreset(Number(field.value)); return true; }
    if (bind === 'sketch-color') { sketch.color = field.value; return true; }
    if (bind === 'sketch-note') { sketch.note = field.value; return true; }
    if (bind === 'sketch-canvas') return true;
    return false;
  } };
}

