:root {
    color-scheme: dark;
    --bg: #090b13;
    --glass-dark: rgba(11, 14, 24, 0.78);
    --glass-border: rgba(255, 255, 255, 0.14);
    --text: #f5f7ff;
    --muted: #b8bed8;
    --accent: #8a7dff;
    --accent-2: #42c8ff;
    --accent-3: #ffb86b;
    --success: #7ceaa3;
    --danger: #ff7f96;
    --shadow: 0 20px 54px rgba(0, 0, 0, 0.45);
}

* {
    box-sizing: border-box;
    -webkit-tap-highlight-color: transparent;
}

html,
body {
    margin: 0;
    width: 100%;
    height: 100%;
    background: var(--bg);
    color: var(--text);
    font-family: "Inter", system-ui, sans-serif;
    overflow: hidden;
