button,
input,
textarea,
select {
    font: inherit;
}

button {
    border: 0;
    color: inherit;
    cursor: pointer;
}

a {
    color: var(--accent-2);
}

textarea,
input,
select {
    width: 100%;
    border: 1px solid rgba(255, 255, 255, 0.12);
    background: rgba(8, 10, 18, 0.6);
    color: var(--text);
    border-radius: 14px;
    padding: 0.75rem 0.9rem;
    outline: none;
}

    textarea:focus,
    input:focus,
    select:focus {
        border-color: rgba(138, 125, 255, 0.65);
        box-shadow: 0 0 0 3px rgba(138, 125, 255, 0.16);
    }

#app {
    position: relative;
    width: 100vw;
    height: 100dvh;
}

#scene {
    width: 100%;
    height: 100%;
    display: block;
    touch-action: none;
}

.glass {
    background: linear-gradient(180deg, rgba(16, 20, 34, 0.84), rgba(10, 12, 22, 0.78));
    border: 1px solid var(--glass-border);
    box-shadow: var(--shadow);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
}

.loading-overlay,
.door-intro {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
    z-index: 30;
    transition: opacity 0.45s ease, visibility 0.45s ease;
}

.loading-overlay {
    background: radial-gradient(circle at center, rgba(138, 125, 255, 0.16), rgba(5, 7, 13, 0.92));
