    padding: 0.42rem 0.7rem;
    border-radius: 999px;
    background: rgba(255, 78, 108, 0.2);
    border: 1px solid rgba(255, 98, 128, 0.65);
    color: #ffdce4;
    font-size: 0.75rem;
    font-weight: 600;
}
.mic-badge[hidden] { display: none; }
.save-lighting-row { justify-content: flex-start; }
.save-toast {
    color: #a8f5d1;
    font-size: 0.78rem;
    font-weight: 600;
}

.hud-volume {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.76rem;
    color: var(--muted);
}
.hud-volume input { width: 68px; accent-color: #9e8cff; }
.mic-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.32rem;
    padding: 0.42rem 0.6rem;
    border-radius: 12px;
    background: rgba(255, 110, 130, 0.18);
    border: 1px solid rgba(255, 120, 140, 0.55);
    color: #ffdde3;
    font-size: 0.76rem;
    white-space: nowrap;
}
.mic-badge[hidden] { display: none; }
.save-lighting-row { justify-content: flex-end; }
.save-toast {
    color: #b6f7c3;
    font-size: 0.8rem;
    animation: fade-out 1.8s ease forwards;
}
@keyframes fade-out {
    0%, 70% { opacity: 1; }
    100% { opacity: 0; }
}

.hud-volume {
    display: flex;
    align-items: center;
    gap: 0.38rem;
    padding: 0.32rem 0.5rem;
    border-radius: 11px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.1);
}
.hud-volume span { font-size: 0.72rem; color: var(--muted); }
.hud-volume input[type="range"] {
    width: 76px;
    accent-color: #9e8cff;
}
.mic-badge {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.32rem 0.55rem;
    border-radius: 11px;
    background: rgba(138, 125, 255, 0.22);
    border: 1px solid rgba(138, 125, 255, 0.58);
    color: #fff;
    font-size: 0.74rem;
    white-space: nowrap;
}
.save-lighting-row {
    justify-content: flex-start;
    gap: 0.75rem;
}
.save-toast {
    font-size: 0.76rem;
    color: #76ffcb;
    animation: saveToastFade 1.6s ease-out forwards;
}
@keyframes saveToastFade {
    0% { opacity: 0; transform: translateY(2px); }
    15% { opacity: 1; transform: translateY(0); }
    75% { opacity: 1; }
    100% { opacity: 0; }
}

    .tooltip.hidden {
        display: none;
    }

.panel-backdrop {
    position: absolute;
    inset: 0;
    z-index: 16;
    background: rgba(4, 5, 10, 0.42);
    transition: opacity 0.25s ease, visibility 0.25s ease;
}

    .panel-backdrop.hidden {
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
    }

.side-panel {
    position: absolute;
    top: 14px;
    right: 14px;
    bottom: 14px;
    z-index: 18;
    width: min(460px, calc(100vw - 28px));
    padding: 1rem;
    border-radius: 26px;
    overflow: hidden;
    transform: translateX(calc(100% + 24px));
    transition: transform 0.28s ease;
}

    .side-panel.open {
        transform: translateX(0);
    }

.panel-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem;
    padding-bottom: 0.85rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

    .panel-head h2 {
        margin: 0.28rem 0 0.3rem;
        font-size: 1.35rem;
    }

    .panel-head p {
        margin: 0;
        color: var(--muted);
        font-size: 0.88rem;
    }

.icon-btn {
    width: 38px;
    height: 38px;
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.12);
    flex-shrink: 0;
}

.panel-content {
    height: calc(100% - 92px);
    overflow-y: auto;
    padding: 0.9rem 0.15rem 0.25rem 0;
}

.module-grid,
.card-stack {
    display: grid;
    gap: 0.9rem;
}

.module-card {
    padding: 0.95rem;
    border-radius: 18px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.09);
}

    .module-card h3 {
        margin: 0 0 0.5rem;
        font-size: 1rem;
    }

    .module-card p {
        margin: 0;
        color: var(--muted);
        line-height: 1.5;
        font-size: 0.9rem;
    }

.row,
.between,
.inline-form {
    display: flex;
    gap: 0.6rem;
    align-items: center;
}

.between {
    justify-content: space-between;
}

.row.wrap,
.preset-row {
    display: flex;
    gap: 0.55rem;
    flex-wrap: wrap;
}

.tiny-btn,
.chip-btn,
.secondary-btn,
.danger-btn,
.primary-btn {
    padding: 0.65rem 0.9rem;
    font-size: 0.88rem;
}

.chip-btn,
.secondary-btn,
.tiny-btn {
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.1);
}

.danger-btn {
    background: rgba(255, 127, 150, 0.16);
    border: 1px solid rgba(255, 127, 150, 0.3);
}

.tiny-btn {
    padding: 0.42rem 0.68rem;
    font-size: 0.8rem;
}

.timer-display {
    font-size: clamp(2rem, 5vw, 3rem);
    font-weight: 800;
    letter-spacing: 0.05em;
    margin: 0.35rem 0;
}

.subtle {
    font-size: 0.84rem;
    color: var(--muted);
}

.chat-thread {
    display: grid;
    gap: 0.7rem;
    max-height: 290px;
    overflow-y: auto;
    padding-right: 0.25rem;
}

.chat-bubble {
    padding: 0.8rem 0.9rem;
    border-radius: 16px;
    line-height: 1.5;
    white-space: pre-wrap;
    font-size: 0.9rem;
}

    .chat-bubble.user {
        background: rgba(138, 125, 255, 0.2);
        border: 1px solid rgba(138, 125, 255, 0.3);
    }

    .chat-bubble.assistant {
        background: rgba(255, 255, 255, 0.06);
        border: 1px solid rgba(255, 255, 255, 0.1);
    }

    .chat-bubble.error {
        background: rgba(255, 127, 150, 0.14);
        border: 1px solid rgba(255, 127, 150, 0.28);
    }

.chat-compose {
    display: grid;
    gap: 0.65rem;
}

    .chat-compose textarea {
        min-height: 95px;
        resize: vertical;
    }

.checklist,
.resource-list,
.pet-log,
.year-stats,
.reminder-list {
    display: grid;
    gap: 0.6rem;
}

.check-item,
.resource-item,
.pet-item,
.year-stat,
.reminder-item {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.7rem;
    padding: 0.75rem 0.85rem;
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.09);
}

    .check-item label {
        display: flex;
        gap: 0.65rem;
        align-items: flex-start;
        width: 100%;
        font-size: 0.9rem;
    }

    .check-item input[type="checkbox"] {
        width: auto;
        margin-top: 0.2rem;
    }

.calendar-grid {
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    gap: 0.4rem;
}

.calendar-day,
.calendar-label {
    min-height: 40px;
    display: grid;
    place-items: center;
    border-radius: 12px;
    font-size: 0.84rem;
}

.calendar-label {
    color: var(--muted);
}

.calendar-day {
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid transparent;
}

    .calendar-day.done {
        background: rgba(124, 234, 163, 0.18);
        border-color: rgba(124, 234, 163, 0.35);
    }

    .calendar-day.today {
        outline: 2px solid rgba(138, 125, 255, 0.65);
    }

    .calendar-day.muted {
        opacity: 0.3;
    }

.slider-row {
    display: grid;
    gap: 0.5rem;
}

input[type="range"] {
    padding: 0;
    background: transparent;
    border: 0;
}

.notebook-area {
    min-height: 180px;
    resize: vertical;
}

.pill {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.35rem 0.68rem;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.08);
    color: var(--muted);
    font-size: 0.8rem;
}

.pulse-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--accent-2);
    animation: pulse 1.8s infinite;
}

.empty-state {
    color: var(--muted);
    padding: 0.9rem;
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px dashed rgba(255, 255, 255, 0.12);
    font-size: 0.88rem;
}

.mono {
    font-variant-numeric: tabular-nums;
}

@keyframes pulse {
    0% {
        box-shadow: 0 0 0 0 rgba(66, 200, 255, 0.55);
    }

    70% {
        box-shadow: 0 0 0 12px rgba(66, 200, 255, 0);
    }

    100% {
        box-shadow: 0 0 0 0 rgba(66, 200, 255, 0);
    }
}

@media (max-width: 1120px) {
    .hud {
        flex-wrap: wrap;
        justify-content: space-between;
    }

    .hud-actions {
        width: 100%;
        overflow-x: auto;
        padding-bottom: 2px;
    }
}

@media (max-width: 720px) {
    .hud {
        top: 10px;
        left: 10px;
        right: 10px;
        padding: 0.6rem 0.7rem;
        gap: 0.5rem;
        border-radius: 18px;
    }

    .brand-copy span {
        display: none;
    }

    .stat-chip {
        min-width: 68px;
        padding: 0.32rem 0.5rem;
    }

    .hud-btn {
        padding: 0.45rem 0.65rem;
        font-size: 0.78rem;
    }

    .help-card {
        top: 132px;
        left: 10px;
        right: 10px;
        width: auto;
    }

    .side-panel {
        left: 10px;
        right: 10px;
        top: auto;
        bottom: 10px;
        width: auto;
        max-height: 76dvh;
        border-radius: 22px;
        transform: translateY(calc(100% + 20px));
    }

        .side-panel.open {
            transform: translateY(0);
        }

    .panel-content {
        height: auto;
        max-height: calc(76dvh - 96px);
    }
}

/* Object-first room controls. Keep panel scrolling separate from the 3D canvas. */
#scene { touch-action: none; }
.room-alarm {
    position: fixed;
    z-index: 30;
    top: max(12px, env(safe-area-inset-top));
    left: 50%;
    transform: translateX(-50%);
    width: max-content;
    max-width: calc(100% - 24px);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;
    gap: 0.65rem;
    padding: 0.65rem;
    border-radius: 16px;
    overflow-wrap: anywhere;
}
.room-alarm[hidden], .room-alarm button[hidden] { display: none; }
.study-form { display: grid; gap: 0.75rem; min-width: 0; }
.study-form input, .study-form select, .study-form textarea { max-width: 100%; min-width: 0; font-size: 1rem; }
.study-form button, .study-list-item button, .room-alarm button { min-height: 44px; }
.study-list-item { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 0.7rem; padding: 0.75rem 0; overflow-wrap: anywhere; }
.study-document { white-space: pre-wrap; overflow-wrap: anywhere; max-height: 38dvh; overflow: auto; padding: 0.75rem; border: 1px solid var(--glass-border); border-radius: 12px; }
.back-to-room { background: var(--glass-dark); border: 1px solid var(--glass-border); min-height: 44px; font-size: 0.8rem; }
.lighting-popover { top: max(14px, env(safe-area-inset-top)); max-height: calc(100dvh - 28px); overflow: auto; }

/* Quick Room Guide: one skippable card, remembered per browser. */
.guide-toggle {
    position: fixed;
    z-index: 18;
    top: max(12px, env(safe-area-inset-top));
    right: max(12px, env(safe-area-inset-right));
    width: 42px;
    height: 42px;
    border-radius: 50%;
    font-size: 1.05rem;
    font-weight: 700;
    background: var(--glass-dark);
    border: 1px solid var(--glass-border);
    box-shadow: var(--shadow);
}
.guide-card {
    position: fixed;
    z-index: 19;
    top: max(62px, calc(env(safe-area-inset-top) + 62px));
    right: max(12px, env(safe-area-inset-right));
    width: min(330px, calc(100vw - 24px));
    max-height: min(76dvh, 560px);
    overflow: auto;
    padding: 1rem 1.1rem;
    border-radius: 20px;
    display: grid;
    gap: 0.6rem;
}
.guide-card ul { margin: 0; padding-left: 1.1rem; display: grid; gap: 0.3rem; font-size: 0.85rem; color: var(--muted); }
.guide-card strong { color: var(--text); }
.guide-hint { margin: 0; font-size: 0.75rem; color: var(--muted); }

/* Study Timer and sketch pad. */
.timer-display-lg { font-size: 2.2rem; text-align: center; letter-spacing: 0.06em; }
.study-sketch { position: relative; touch-action: none; width: 100%; aspect-ratio: 4 / 3; border-radius: 12px; border: 1px solid var(--glass-border); background: #fff; cursor: crosshair; }
.study-swatches { display: flex; flex-wrap: wrap; gap: 0.35rem; align-items: center; }
.study-swatches input[type="color"] { width: 40px; height: 32px; padding: 0; }

/* Monthly calendar. */
.study-month { display: grid; gap: 0.5rem; }
.study-month-head { display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; }
.study-month-grid { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 4px; }
.study-month-grid .study-dow { text-align: center; font-size: 0.7rem; color: var(--muted); padding-bottom: 0.15rem; }
.study-day { position: relative; min-height: 40px; border-radius: 9px; border: 1px solid var(--glass-border); background: rgba(255, 255, 255, 0.03); padding: 0.2rem 0.3rem; font-size: 0.78rem; text-align: left; overflow-wrap: anywhere; }
.study-day[aria-pressed="true"] { border-color: var(--accent); box-shadow: inset 0 0 0 1px var(--accent); }
.study-day .study-day-dot { position: absolute; right: 6px; bottom: 5px; width: 6px; height: 6px; border-radius: 50%; background: var(--accent-2); }
.study-day[data-today] { border-color: var(--accent-3); }
.study-tasks { display: grid; gap: 0.55rem; }
.study-tasks .study-task { border: 1px solid var(--glass-border); border-radius: 12px; padding: 0.6rem 0.7rem; display: grid; gap: 0.3rem; }

.study-thumb { width: 100%; max-width: 210px; display: block; border-radius: 12px; border: 1px solid var(--glass-border); background: #fff; object-fit: cover; }
.study-list-item img.study-thumb { width: 74px; height: 74px; flex: none; }
.reader-image { width: 100%; max-width: 320px; display: block; border-radius: 14px; border: 1px solid var(--glass-border); margin: 0 auto; }
